package com.example

import com.example.ExamQuestionHelper.QSpec

internal object HistoryLiveExamWorldRevBank {
  private const val T = "යුරෝපීය පුනරුදය, භූගෝලීය ගවේෂණ හා විප්ලව"

  private fun q(
    t: String,
    s: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    e: String
  ) = QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun renaissanceAndRevolutionsQuestions(): List<QSpec> = listOf(
    q(T, "යුරෝපයේ 'පුනරුදය' (Renaissance) යන වචනයේ සරල අර්ථය කුමක්ද?", "නැවත උපත හෙවත් පුනර්ජීවනය (Rebirth)", "නව යුද්ධය", "ආගමික වෙනස", "කාර්මික දියුණුව", "මධ්‍යතන යුගයේ අඳුරෙන් මිදී පැරණි ග්‍රීක හා රෝම ශිෂ්ටාචාරවල ඥානය හා කලාව යළි පිබිදීම පුනරුදයයි."),
    q(T, "ක්‍රි.ව. 1453 දී ඔටෝමාන් තුර්කිවරුන් විසින් අත්පත් කරගන්නා ලද නැගෙනහිර රෝම අධිරාජ්‍යයේ අගනුවර කුමක්ද?", "කොන්ස්තන්තිනෝපලය (Constantinople)", "ඇතැන්ස්", "රෝමය", "ඇලෙක්සැන්ඩ්‍රියාව", "කොන්ස්තන්තිනෝපලය බිඳවැටීමත් සමඟ ග්‍රීක පඬිවරු පුස්කොළ පොත් රැගෙන ඉතාලියේ නගරවලට පලා ගියහ."),
    q(T, "යුරෝපීය පුනරුදය මුලින්ම ආරම්භ වූ රට කුමක්ද?", "ඉතාලිය", "එංගලන්තය", "ප්‍රංශය", "ස්පාඤ්ඤය", "ෆ්ලොරන්ස්, වැනිස්, ජිනෝවා, මිලාන් හා රෝමය වැනි ස්වාධීන ධනවත් වෙළෙඳ නගර පිහිටි ඉතාලියේ පුනරුදය ඇරඹිණි."),
    q(T, "පුනරුද යුගයේ බිහිවූ 'මානවවාදයේ පියා' (Father of Humanism) ලෙස සැලකෙන්නේ කවුද?", "ෆ්‍රැන්සෙස්කෝ පෙට්‍රාක් (Francesco Petrarch)", "ඩැන්ටේ", "බොකෑචියෝ", "එරැස්මස්", "මධ්‍යතන ආගමික කේන්ද්‍රීය චින්තනය වෙනුවට මිනිසා හා ඔහුගේ මෙලොව ජීවිතය අගය කළ පෙට්‍රාක් මානවවාදයේ පියායි."),
    q(T, "ඉතාලි ජාතික ඩැන්ටේ ඇලිගියරි විසින් රචනා කරන ලද ලෝක ප්‍රසිද්ධ කාව්‍ය ග්‍රන්ථය කුමක්ද?", "දිව්‍ය ප්‍රහසනය (The Divine Comedy)", "ඩෙකැමරන්", "යුතෝපියාව", "කුමාරයා", "ඉතාලි ජන බසින් රචිත දිව්‍ය ප්‍රහසනය මධ්‍යතන යුගයේ සිට පුනරුදයට මාරුවීම සනිටුහන් කරයි."),
    q(T, "ජියෝවානි බොකෑචියෝ විසින් කළු මරණය (මහා වසංගතය) පසුබිම් කරගෙන රචිත කෘතිය කුමක්ද?", "ඩෙකැමරන් (The Decameron)", "මෝඩකමේ පැසසුම", "කුමාරයා", "නව ඇට්ලෑන්ටිස්", "තරුණ තරුණියන් පිරිසක් කියන කතා සියයකින් සමන්විත ඩෙකැමරන් මානව හැඟීම් මනාව විදහාපායි."),
    q(T, "ක්‍රිස්තියානි පල්ලියේ සහ පූජකයන්ගේ දූෂණ හා මිථ්‍යා විශ්වාස උපහාසයට ලක් කරමින් එරැස්මස් ලියූ කෘතිය කුමක්ද?", "මෝඩකමේ පැසසුම (Praise of Folly)", "යුතෝපියාව", "දිව්‍ය ප්‍රහසනය", "දේශපාලනය", "ලතින් බසින් රචිත මෙම කෘතිය පුනරුද මානවවාදී සාහිත්‍යයේ විශිෂ්ට උපහාසාත්මක නිර්මාණයකි."),
    q(T, "ඉංග්‍රීසි ජාතික ශ්‍රීමත් තෝමස් මෝර් විසින් පරමාදර්ශී පරිපූර්ණ සමාජයක් ගැන ලියූ කෘතිය කුමක්ද?", "යුතෝපියාව (Utopia)", "කුමාරයා", "ලෙවියතන්", "සමාජ සම්මුතිය", "පොදු දේපළ හිමිකම හා සාමය පවතින පරමාදර්ශී දූපතක් ගැන යුතෝපියාවෙහි විස්තර කෙරේ."),
    q(T, "දේශපාලන බලය ලබා ගැනීම හා පවත්වාගෙන යාම පිළිබඳ නිකොලෝ මැකියාවෙලි රචනා කළ කෘතිය කුමක්ද?", "කුමාරයා (The Prince)", "යුතෝපියාව", "දේශපාලන විද්‍යාව", "ජනරජය", "රාජ්‍ය පාලකයා නරියා මෙන් කපටි හා සිංහයා මෙන් ප්‍රචණ්ඩ විය යුතු යැයි මැකියාවෙලි තර්ක කළේය."),
    q(T, "පුනරුද කලාවේ විශිෂ්ටතම නිර්මාණයක් වන 'මොනාලිසා' (Mona Lisa) සිතුවම ඇඳි කලාකරුවා කවුද?", "ලියනාඩෝ ඩා වින්චි (Leonardo da Vinci)", "මයිකල් ආන්ජලෝ", "රෆායෙල්", "ඩොනටෙලෝ", "අභිරහස් සිනහවකින් යුත් මොනාලිසා සිතුවම ලෝකයේ වඩාත්ම ප්‍රසිද්ධ චිත්‍රය ලෙස සැලකේ."),
    q(T, "ක්‍රිස්තුස් වහන්සේ තම ගෝලයන් සමඟ ගත් අවසාන රාත්‍රී භෝජනය නිරූපණය කරන 'අවසාන භෝජන සංග්‍රහය' (The Last Supper) සිතුවම ඇන්දේ කවුද?", "ලියනාඩෝ ඩා වින්චි", "මයිකල් ආන්ජලෝ", "රෆායෙල්", "ටිටියන්", "මිලාන්හි සැන්ටා මරියා ඩෙල් ග්‍රාසි දේවස්ථානයේ බිත්තියේ මෙම සිතුවම ඇඳ ඇත."),
    q(T, "වතිකානයේ සිස්ටීන් දේවස්ථානයේ (Sistine Chapel) සිවිලිමේ ආදම්ගේ මැවීම ඇතුළු බයිබල් කතා සිතුවම් කළේ කවුද?", "මයිකල් ආන්ජලෝ (Michelangelo)", "ඩා වින්චි", "රෆායෙල්", "ඩොනටෙලෝ", "වසර හතරක් උඩුබැලි අතට වැතිර සිටිමින් මයිකල් ආන්ජලෝ සිස්ටීන් සිවිලිමේ සිතුවම් නිම කළේය."),
    q(T, "මයිකල් ආන්ජලෝ විසින් කිරිගරුඬින් නෙළන ලද තරුණ ඩේවිඩ්ගේ සහ මළ ක්‍රිස්තුස් වහන්සේ උකුල මත තබාගත් මරියා තුමියගේ ප්‍රතිමා දෙක මොනවාද?", "ඩේවිඩ් (David) සහ පියෙටා (Pieta)", "මොනාලිසා", "ඇතැන්ස් ගුරුකුලය", "මෝසෙස්", "මිනිස් සිරුරේ මාංශපේශී හා නහර ඉතා සියුම්ව කිරිගරුඬ ගලින් නෙළීමේ විස්මිත ප්‍රතිභාව පෙන්වයි."),
    q(T, "වතිකානු මාලිගයේ 'ඇතැන්ස් ගුරුකුලය' (The School of Athens) නම් ප්ලේටෝ හා ඇරිස්ටෝටල් සිටින විශිෂ්ට බිතුසිතුවම ඇන්දේ කවුද?", "රෆායෙල් සැන්සියෝ (Raphael)", "ඩා වින්චි", "මයිකල් ආන්ජලෝ", "ජොටෝ", "පැරණි ග්‍රීක දාර්ශනිකයන් සහ විද්‍යාඥයන් එකල රෝමයේ ගොඩනැගිල්ලක සාකච්ඡා කරන අයුරු මනරම්ව පෙන්වයි."),
    q(T, "ක්‍රි.ව. 1455 දී ලොව ප්‍රථම වරට චංචල ලෝහ අකුරු භාවිත කරමින් මුද්‍රණ යන්ත්‍රය සොයාගත් ජර්මන් ජාතිකයා කවුද?", "යොහෑන්ස් ගුටෙන්බර්ග් (Johannes Gutenberg)", "තෝමස් අල්වා එඩිසන්", "ජේම්ස් වොට්", "අයිසැක් නිව්ටන්", "ගුටෙන්බර්ග් මුද්‍රණාලයෙන් ප්‍රථමයෙන් මුද්‍රණය කළේ ලතින් බයිබලයයි (ගුටෙන්බර්ග් බයිබලය)."),
    q(T, "මුද්‍රණ යන්ත්‍රය සොයා ගැනීම නිසා යුරෝපයේ සිදුවූ ප්‍රධානතම සමාජ පෙරළිය කුමක්ද?", "පොත්පත් විශාල වශයෙන් ලාභදායීව මුද්‍රණය වී සාමාන්‍ය ජනයා අතර දැනුම වේගයෙන් ව්‍යාප්ත වීම", "පොත්පත් තහනම් වීම", "භාෂා විනාශ වීම", "ආගම නැතිවීම", "පුස්කොළ හා අතින් ලියන ලද අත්පිටපත් වෙනුවට මුද්‍රිත පොත් බිහිවීමෙන් විද්‍යාත්මක හා ආගමික පුනරුදය වේගවත් විය."),
    q(T, "සෞරග්‍රහ මණ්ඩලයේ කේන්ද්‍රය පෘථිවිය නොව සූර්යයා බව පෙන්වා දෙමින් 'හිරු කේන්ද්‍රවාදය' (Heliocentric theory) ඉදිරිපත් කළ පෝලන්ත තාරකා විද්‍යාඥයා කවුද?", "නිකොලස් කොපර්නිකස් (Nicolaus Copernicus)", "ටොලමි", "ගැලීලියෝ ගැලිලි", "අයිසැක් නිව්ටන්", "පෘථිවි කේන්ද්‍රවාදය බිඳ දමමින් සූර්යයා කේන්ද්‍රයේ තබා ග්‍රහලෝක භ්‍රමණය වන බව කොපර්නිකස් තහවුරු කළේය."),
    q(T, "දුරේක්ෂය (Telescope) වැඩිදියුණු කර අභ්‍යවකාශ නිරීක්ෂණය කර බ්‍රහස්පතිගේ චන්ද්‍රයන් හා සඳෙහි ආවාට සොයාගත් ඉතාලි විද්‍යාඥයා කවුද?", "ගැලීලියෝ ගැලිලි (Galileo Galilei)", "කොපර්නිකස්", "කෙප්ලර්", "නිව්ටන්", "පල්ලියේ විරෝධය හමුවේ වුවද කොපර්නිකස්ගේ මතය සත්‍ය බව ගැලීලියෝ දුරේක්ෂයෙන් ඔප්පු කළේය."),
    q(T, "ග්‍රහලෝක සූර්යයා වටා ගමන් කරන්නේ ඉලිප්සාකාර කක්ෂවල බව සොයාගත් ජර්මානු තාරකා විද්‍යාඥයා කවුද?", "ජොහැන්නස් කෙප්ලර් (Johannes Kepler)", "ගැලීලියෝ", "නිව්ටන්", "කොපර්නිකස්", "ග්‍රහලෝකවල වේගය හා කක්ෂ පිළිබඳ කෙප්ලර්ගේ නියමයන් නූතන තාරකා විද්‍යාවේ පදනම විය."),
    q(T, "විශ්ව ගුරුත්වාකර්ෂණ නියමය (Law of Universal Gravitation) සහ චලිතය පිළිබඳ නියම තුන ඉදිරිපත් කළ ඉංග්‍රීසි විද්‍යාඥයා කවුද?", "ශ්‍රීමත් අයිසැක් නිව්ටන් (Sir Isaac Newton)", "ගැලීලියෝ", "විලියම් හාවි", "ඇල්බට් අයින්ස්ටයින්", "1687 දී 'ප්‍රින්සිපියා මැතමැටිකා' ග්‍රන්ථය ප්‍රකාශයට පත් කරමින් භෞතික විද්‍යාවේ මහා පෙරළියක් කළේය."),
    q(T, "මිනිස් සිරුරේ හෘදය වස්තුව මගින් ලේ පොම්ප කර රුධිර සංසරණය සිදුවන ආකාරය සොයාගත් විද්‍යාඥයා කවුද?", "විලියම් හාවි (William Harvey)", "ඇන්ඩ්‍රියාස් විසාලියස්", "එඩ්වඩ් ජෙනර්", "ලුවී පාස්චර්", "ලේ නහර හා කපාට ක්‍රියාකාරීත්වය විස්තර කරමින් වෛද්‍ය විද්‍යාවේ නව යුගයක් ඇරඹීය."),
    q(T, "මළ සිරුරු විච්ඡේදනය කර මිනිස් සිරුරේ අභ්‍යන්තර ව්‍යුහය පිළිබඳ නිරවද්‍ය විස්තර ලියූ ව්‍යුහ විද්‍යාවේ පියා කවුද?", "ඇන්ඩ්‍රියාස් විසාලියස් (Andreas Vesalius)", "විලියම් හාවි", "හිපොක්‍රටීස්", "ගැලන්", "මධ්‍යතන ගැලන්ගේ වැරදි මත නිවැරදි කරමින් 'ද හියුමනි කෝපොරිස් ෆැබ්රිකා' ග්‍රන්ථය විසාලියස් පළ කළේය."),
    q(T, "15 වන සියවසේදී යුරෝපීයයන් නව මුහුදු මාර්ග සෙවීමට පෙළඹවූ ප්‍රධාන ආර්ථික සාධකය කුමක්ද?", "ඔටෝමාන් තුර්කිවරුන් පෙරදිග ගොඩබිම් වෙළෙඳ මාර්ග අවහිර කිරීම නිසා කුළුබඩු සඳහා මුහුදු මගක් සෙවීම", "යුරෝපයේ ජනගහනය අඩුවීම", "කෘෂිකර්මය නතර වීම", "මුහුදු ගමන් විනෝදාංශයක් වීම", "ඉන්දියාවෙන් හා මලක්කාවෙන් කුළුබඩු ලබා ගැනීමට කෙළින්ම මුහුදු මාර්ගයක් අවශ්‍ය විය."),
    q(T, "භූගෝලීය ගවේෂණ යුගයේදී නාවිකයන්ගේ ගමනට උපකාරී වූ ප්‍රධාන තාක්ෂණික උපකරණ මොනවාද?", "චුම්භක මාලිමාව (Magnetic Compass), තාරකා මිනුම් උපකරණය (Astrolabe) හා කැරවල් නැව්", "රේඩාර් යන්ත්‍ර", "චන්ද්‍රිකා සන්නිවේදනය", "වාෂ්ප එන්ජින්", "චීනයෙන් හා අරාබියෙන් ලබාගත් මාලිමාව හා ඇස්ට්‍රොලේබය සාගරයේ දිශාව හා පිහිටීම දැන ගැනීමට උපකාරී විය."),
    q(T, "පෘතුගාලයේ නාවික පාසලක් පිහිටුවා නාවිකයන් පුහුණු කර ගවේෂණ දිරිමත් කළ රජකුමරු කවුද?", "නාවික හෙන්රි කුමරු (Prince Henry the Navigator)", "මැනුවෙල් රජු", "ජෝන් රජු", "ෆර්ඩිනන්ඩ් රජු", "සාග්‍රෙස්හි නාවික ඇකඩමියක් පිහිටුවා අප්‍රිකානු වෙරළ ගවේෂණයට නැව් පිටත් කළේය."),
    q(T, "අප්‍රිකා මහද්වීපයේ දකුණු කෙළවර වන 'යහපත් බලාපොරොත්තුවේ තුඩුව' (Cape of Good Hope) සොයාගත් පෘතුගීසි නාවිකයා කවුද?", "බර්තොලමියු ඩයස් (Bartholomew Dias)", "වාස්කෝ ද ගාමා", "ක්‍රිස්ටෝෆර් කොලොම්බස්", "මැගලන්", "ක්‍රි.ව. 1488 දී අප්‍රිකාවේ දකුණු තුඩුව පසුකර ඉන්දියන් සාගරයට මුහුදු මග විවෘත කළේය."),
    q(T, "ක්‍රි.ව. 1498 දී අප්‍රිකාව වටා යාත්‍රා කර ඉන්දියාවේ කැලිකට් (කාලිකට්) වරායට ළඟාවූ ප්‍රථම යුරෝපීය නාවිකයා කවුද?", "වාස්කෝ ද ගාමා (Vasco da Gama)", "බර්තොලමියු ඩයස්", "ලොරෙන්සෝ ද අල්මේදා", "අෆොන්සෝ ද අල්බුකර්ක්", "යුරෝපයේ සිට ඉන්දියාවට සම්පූර්ණ මුහුදු මාර්ගය සොයා ගැනීම ලෝක වෙළෙඳාමේ මහා හැරවුම් ලක්ෂ්‍යයක් විය."),
    q(T, "ක්‍රි.ව. 1492 දී ස්පාඤ්ඤයේ අනුග්‍රහයෙන් බටහිර දෙසට යාත්‍රා කර අමෙරිකානු මහද්වීපය සොයාගත් ඉතාලි ජාතික නාවිකයා කවුද?", "ක්‍රිස්ටෝෆර් කොලොම්බස් (Christopher Columbus)", "අමරිගෝ වෙස්පුචි", "මැගලන්", "කැබ්රාල්", "ඉන්දියාව සොයා බටහිරට ගිය කොලොම්බස් බහමාස් දූපත්වලට ළඟා වී ඒවා 'බටහිර ඉන්දීය කොදෙව්' ලෙස නම් කළේය."),
    q(T, "කොලොම්බස් සොයාගත්තේ නව මහාද්වීපයක් බව මුලින්ම තහවුරු කළ බැවින් අමෙරිකාව ඔහුගේ නමින් නම් කළ නාවිකයා කවුද?", "අමරිගෝ වෙස්පුචි (Amerigo Vespucci)", "කොලොම්බස්", "ජෝන් කැබට්", "ෆ්‍රැන්සිස් ඩ්‍රේක්", "දකුණු අමෙරිකානු වෙරළ දිගේ යාත්‍රා කරමින් මෙය ආසියාව නොව නව ලෝකයක් (New World) බව පෙන්වා දුන්නේය."),
    q(T, "ක්‍රි.ව. 1519 සිට 1522 දක්වා ලොව වටා ප්‍රථම වරට සාගර චාරිකාවක යෙදුණු නාවික ගවේෂකයා කවුද?", "ෆර්ඩිනන්ඩ් මැගලන් (Ferdinand Magellan)", "වාස්කෝ ද ගාමා", "කොලොම්බස්", "ජේම්ස් කුක්", "මැගලන් පිලිපීනයේදී මියගියද ඔහුගේ නියමුවා වූ ජුවාන් සෙබස්තියන් එල්කානෝ වික්ටෝරියා නෞකාවෙන් ලොව වටා ගමන සම්පූර්ණ කළේය."),
    q(T, "භූගෝලීය ගවේෂණවලින් පසු අත්ලාන්තික් සාගරය හරහා යුරෝපය, අප්‍රිකාව හා අමෙරිකාව අතර ඇතිවූ වෙළෙඳ රටාව කුමක්ද?", "ත්‍රිකෝණාකාර වෙළෙඳාම (Triangular Trade)", "සේද මාවත", "කුළුබඩු මාවත", "සහරා වෙළෙඳාම", "යුරෝපයෙන් කාර්මික භාණ්ඩ අප්‍රිකාවටත්, අප්‍රිකාවෙන් වහලුන් අමෙරිකාවටත්, අමෙරිකාවෙන් සීනි හා දුම්කොළ යුරෝපයටත් ප්‍රවාහනය කෙරිණි."),
    q(T, "භූගෝලීය ගවේෂණවල ප්‍රතිඵලයක් ලෙස අමෙරිකානු මහද්වීපයෙන් යුරෝපයට හා ආසියාවට හඳුන්වා දුන් නව කෘෂිකාර්මික බෝග මොනවාද?", "අර්තාපල්, බඩඉරිඟු, තක්කාලි, දුම්කොළ, මඤ්ඤොක්කා සහ රබර්", "තිරිඟු සහ බාර්ලි", "සහල් පමණක්", "තේ සහ කුරුඳු", "නව ලෝකයෙන් ලැබුණු මෙම ආහාර බෝග ලෝක ජනගහනයේ ආහාර සුරක්ෂිතතාවට දැවැන්ත බලපෑමක් කළේය."),
    q(T, "18 වන සියවසේ මැද භාගයේදී 'කාර්මික විප්ලවය' (Industrial Revolution) ප්‍රථමයෙන්ම ආරම්භ වූ රට කුමක්ද?", "බ්‍රිතාන්‍යය (එංගලන්තය)", "ප්‍රංශය", "ජර්මනිය", "ඇමරිකාව", "යකඩ හා ගල් අඟුරු නිධි, ප්‍රාග්ධනය, යටත් විජිත වෙළෙඳපොළ හා දේශපාලන ස්ථාවරත්වය නිසා බ්‍රිතාන්‍යයේ කාර්මික විප්ලවය ඇරඹිණි."),
    q(T, "කාර්මික විප්ලවයේදී යන්ත්‍ර සූත්‍ර භාවිතය මුලින්ම ආරම්භ වූ ප්‍රධාන කර්මාන්ත ක්ෂේත්‍රය කුමක්ද?", "රෙදිපිළි (කපු ඇඟලුම්) කර්මාන්තය", "මෝටර් රථ කර්මාන්තය", "ගුවන් යානා කර්මාන්තය", "රසායනික කර්මාන්තය", "නූල් කැටීම හා රෙදි විවීම වේගවත් කිරීම සඳහා ප්‍රථම යන්ත්‍රෝපකරණ රැසක් නිර්මාණය විය."),
    q(T, "ක්‍රි.ව. 1733 දී රෙදි විවීමේ කාර්යක්ෂමතාව දෙගුණයකින් වැඩි කළ 'පියාඹන නඩාව' (Flying Shuttle) සොයාගත් පුද්ගලයා කවුද?", "ජෝන් කේ (John Kay)", "ජේම්ස් හාග්‍රීව්ස්", "රිචඩ් ආක්රයිට්", "එඩ්මන්ඩ් කාට්රයිට්", "පියාඹන නඩාව නිසා රෙදි විවීම වේගවත් වී නූල් හිඟයක් නිර්මාණය විය."),
    q(T, "එකවර නූල් කරල් අටක් කැටිය හැකි 'ස්පිනින් ජෙනී' (Spinning Jenny) නූල් කටින යන්ත්‍රය සොයාගත්තේ කවුද?", "ජේම්ස් හාග්‍රීව්ස් (James Hargreaves)", "ජෝන් කේ", "ජේම්ස් වොට්", "තෝමස් නිව්කොමන්", "තම දියණිය වූ ජෙනී සිහිවීම පිණිස නම් කළ මෙම යන්ත්‍රය නූල් කැටීමේ වේගය අතිමහත් ලෙස වැඩිකළේය."),
    q(T, "ජල බලයෙන් ක්‍රියාත්මක වූ 'වෝටර් ෆ්‍රේම්' (Water Frame) නූල් කටින යන්ත්‍රය සොයාගත් පුද්ගලයා කවුද?", "රිචඩ් ආක්රයිට් (Richard Arkwright)", "ජේම්ස් හාග්‍රීව්ස්", "සැමුවෙල් ක්‍රොම්ප්ටන්", "එලි විට්නි", "ජල බලය යොදා ගැනීම නිසා වැඩපළවල් ගංගා අසබඩ විශාල කර්මාන්තශාලා බවට පත්විය."),
    q(T, "හාග්‍රීව්ස්ගේ සහ ආක්රයිට්ගේ යන්ත්‍ර දෙකෙහිම ගුණාංග එකතු කර 'ස්පිනින් මියුල්' (Spinning Mule) යන්ත්‍රය හැදුවේ කවුද?", "සැමුවෙල් ක්‍රොම්ප්ටන් (Samuel Crompton)", "ජෝන් කේ", "එඩ්මන්ඩ් කාට්රයිට්", "ජේම්ස් වොට්", "අතිශය සිහින් හා ශක්තිමත් උසස් තත්ත්වයේ නූල් නිපදවීමට මියුල් යන්ත්‍රයට හැකිවිය."),
    q(T, "කාර්මික විප්ලවයේදී වාෂ්ප බලයෙන් ක්‍රියා කළ ප්‍රථම 'බලවේග රෙදි වියන' (Power Loom) නිර්මාණය කළේ කවුද?", "එඩ්මන්ඩ් කාට්රයිට් (Edmund Cartwright)", "ජෝන් කේ", "රිචඩ් ආක්රයිට්", "ජේම්ස් හාග්‍රීව්ස්", "ජල හෝ වාෂ්ප බලයෙන් ස්වයංක්‍රීයව රෙදි වියන බලවේග රෙදි වියන නිසා රෙදිපිළි නිෂ්පාදනය දැවැන්ත විය."),
    q(T, "කපු බීජවලින් කපු පුළුන් වෙන් කිරීම පහසු කළ 'කොට්න් ජින්' (Cotton Gin) යන්ත්‍රය සොයාගත් අමෙරිකානුවා කවුද?", "එලි විට්නි (Eli Whitney)", "තෝමස් එඩිසන්", "ඇලෙක්සැන්ඩර් ග්‍රැහැම් බෙල්", "හෙන්රි ෆෝඩ්", "කපු වගාවේ අස්වැන්න සැකසීම සිය ගුණයකින් වේගවත් කිරීමට කොට්න් ජින් යන්ත්‍රය සමත් විය."),
    q(T, "කාර්මික විප්ලවයේ ජීවනාලිය වූ 'කාර්යක්ෂම වාෂ්ප එන්ජිම' (Steam Engine) 1769 දී වැඩිදියුණු කර නිපදවූයේ කවුද?", "ජේම්ස් වොට් (James Watt)", "තෝමස් නිව්කොමන්", "ජෝර්ජ් ස්ටීවන්සන්", "රොබට් ෆුල්ටන්", "නිව්කොමන්ගේ පැරණි වාෂ්ප පොම්පය වෙනුවට ඝනීභවනය වෙනම සිදුකළ ජේම්ස් වොට්ගේ එන්ජිම යන්ත්‍ර ධාවනයට යෙදවිණි."),
    q(T, "ක්‍රි.ව. 1814 දී 'රොකට්' (The Rocket) නම් ප්‍රථම වාෂ්ප දුම්රිය එන්ජිම සාර්ථකව ධාවනය කළ ඉංජිනේරුවා කවුද?", "ජෝර්ජ් ස්ටීවන්සන් (George Stephenson)", "ජේම්ස් වොට්", "තෝමස් එඩිසන්", "හෙන්රි බෙස්මර්", "මැන්චෙස්ටර් සිට ලිවර්පූල් දක්වා ප්‍රථම මගී දුම්රිය මාර්ගය විවෘත වීමෙන් ගමනාගමනයේ මහා පෙරළියක් විය."),
    q(T, "ලොව ප්‍රථම වාණිජ වාෂ්ප නැව වූ 'ක්ලර්මොන්ට්' (Clermont) සාර්ථකව ධාවනය කළ ඇමරිකානු නව නිපැයුම්කරු කවුද?", "රොබට් ෆුල්ටන් (Robert Fulton)", "ජෝර්ජ් ස්ටීවන්සන්", "ජේම්ස් වොට්", "මැකඩම්", "හුඩ්සන් නදියේ ධාවනය වූ මෙම වාෂ්ප නෞකාව සාගර යාත්‍රා කලාවේ නව යුගයක් සලකුණු කළේය."),
    q(T, "ගල් කුඩු හා තාර යොදා ගනිමින් වැසි ජලයෙන් විනාශ නොවන ශක්තිමත් නව මාර්ග ඉදිකිරීමේ ක්‍රමය (Macadamization) සොයාගත්තේ කවුද?", "ජෝන් මැකඩම් (John McAdam)", "ජෝර්ජ් ස්ටීවන්සන්", "ජේම්ස් වොට්", "තෝමස් ටෙල්ෆර්ඩ්", "නූතන තාර දැමූ මහාමාර්ග පද්ධතියේ පදනම වූයේ මැකඩම්ගේ ඉංජිනේරු ක්‍රමයයි."),
    q(T, "කාර්මික විප්ලවය නිසා බිහිවූ නව සමාජ පන්ති දෙක මොනවාද?", "ධනපති පන්තිය (කාර්මික හිමිකරුවන්) සහ නිර්ධන පන්තිය (කම්කරු පන්තිය)", "රජවරුන් සහ වහලුන්", "පූජකයන් සහ ගොවීන්", "වංශවතුන් සහ සේවකයන්", "යන්ත්‍ර සූත්‍ර හා කර්මාන්තශාලා හිමි ධනපතියන් සහ ශ්‍රමය විකුණා ජීවත් වන කම්කරු පන්තිය අතර අරගලයක් බිහිවිය."),
    q(T, "කාර්මික විප්ලවයේ මුල් අවධියේදී කම්කරුවන් තම රැකියා අහිමි වීමට හේතුව යන්ත්‍ර සූත්‍ර යැයි සිතා ඒවා කඩා බිඳ දැමූ ව්‍යාපාරය කුමක්ද?", "ලුඩයිට් ව්‍යාපාරය (Luddite Movement)", "චාටිස්ට් ව්‍යාපාරය", "සමාජවාදී ව්‍යාපාරය", "විප්ලවවාදී ව්‍යාපාරය", "නෙඩ් ලුඩ් නමැත්තාගේ නායකත්වයෙන් යන්ත්‍ර කුඩුපට්ටම් කරමින් කම්කරුවෝ විරෝධය පෑහ."),
    q(T, "කාර්මික විප්ලවයේදී කර්මාන්තශාලාවල සේවය කළ ළමුන් හා කාන්තාවන්ගේ සේවා තත්ත්වයන් වැඩිදියුණු කිරීමට බ්‍රිතාන්‍යය පැනවූ නීති මොනවාද?", "කර්මාන්තශාලා පනත් (Factory Acts - උදා: 1833 පනත)", "දුප්පත් නීති", "ධාන්‍ය නීති", "නාවික පනත්", "ළමා ශ්‍රමය සීමා කරමින් දිනකට වැඩ කරන පැය ගණන නීතිගත කිරීමට මෙමගින් පියවර ගැනිණි."),
    q(T, "කාර්මික විප්ලවයේ කෲර ධනවාදී සූරාකෑම විවේචනය කරමින් 'කොමියුනිස්ට් ප්‍රකාශනය' සහ 'ප්‍රාග්ධනය' (Das Kapital) ලියූ දාර්ශනිකයන් දෙදෙනා කවුද?", "කාල් මාක්ස් සහ ෆ්‍රෙඩ්රික් එංගල්ස් (Karl Marx & Friedrich Engels)", "ඇඩම් ස්මිත් හා ඩේවිඩ් රිකාඩෝ", "වෝල්ටෙයාර් හා රූසෝ", "ලොක් හා හොබ්ස්", "විද්‍යාත්මක සමාජවාදය හඳුන්වා දෙමින් කම්කරු පන්තියේ විප්ලවයකින් සමාජවාදය බිහිවන බව ප්‍රකාශ කළහ."),
    q(T, "අමෙරිකානු නිදහස් සටන (1775-1783) ඇතිවීමට පෙර උතුරු අමෙරිකාවේ පිහිටුවා තිබූ බ්‍රිතාන්‍ය යටත් විජිත සංඛ්‍යාව කීයද?", "යටත් විජිත දහතුනකි (13)", "යටත් විජිත විස්සකි", "යටත් විජිත පහකි", "යටත් විජිත පනහකි", "අත්ලාන්තික් වෙරළ තීරයේ පිහිටි ජෝර්ජියා, වර්ජිනියා, මැසචුසෙට්ස් ආදී ජනපද 13කි."),
    q(T, "බ්‍රිතාන්‍ය පාර්ලිමේන්තුව අමෙරිකානු ජනපද මත බදු පැනවීමට විරුද්ධව අමෙරිකානුවන් නැගූ සුප්‍රකට සටන් පාඨය කුමක්ද?", "නියෝජනයක් නැතිනම් බදු නැත (No Taxation Without Representation)", "නිදහස නැතිනම් මරණය", "සහෝදරත්වය හා සාමය", "රජුට ජය වේවා", "බ්‍රිතාන්‍ය පාර්ලිමේන්තුවේ තම නියෝජිතයන් නැති බැවින් බදු පැනවීමට අයිතියක් නැතැයි ඔවුහු තර්ක කළහ."),
    q(T, "ක්‍රි.ව. 1773 දී අමෙරිකානු නිදහස් සටනට මඟපෑදූ තේ බද්දට විරෝධය පාමින් තේ පෙට්ටි මුහුදට විසි කළ සිදුවීම කුමක්ද?", "බොස්ටන් තේ සාදය (Boston Tea Party)", "නිව්යෝර්ක් කැරැල්ල", "වොෂින්ටන් විරෝධය", "ෆිලඩෙල්ෆියා ප්‍රකාශය", "රතු ඉන්දියානුවන් සේ වෙස්වලාගත් පිරිසක් බොස්ටන් වරායේ නැව්වල තිබූ තේ පෙට්ටි 342ක් මුහුදට දැමූහ."),
    q(T, "අමෙරිකානු නිදහස් සටනේදී යටත් විජිත හමුදාවන්ගේ ප්‍රධාන සෙන්පතිවරයා ලෙස පත්වී සටන මෙහෙයවූයේ කවුද?", "ජෝර්ජ් වොෂින්ටන් (George Washington)", "තෝමස් ජෙෆර්සන්", "බෙන්ජමින් ෆ්‍රෑන්ක්ලින්", "ඒබ්‍රහම් ලින්කන්", "වොෂින්ටන්ගේ නායකත්වයෙන් යුත් ඇමරිකානු හමුදාව බ්‍රිතාන්‍ය අධිරාජ්‍යවාදී හමුදා පරාජය කළේය."),
    q(T, "ක්‍රි.ව. 1776 ජූලි 04 වන දින සම්මත කරන ලද 'අමෙරිකානු නිදහස් ප්‍රකාශනය' (Declaration of Independence) කෙටුම්පත් කළ ප්‍රධාන පුද්ගලයා කවුද?", "තෝමස් ජෙෆර්සන් (Thomas Jefferson)", "ජෝර්ජ් වොෂින්ටන්", "ජෝන් ඇඩම්ස්", "ඇලෙක්සැන්ඩර් හැමිල්ටන්", "සියලු මිනිසුන් සමානව මවන ලද බවත් ජීවත් වීමේ හා නිදහසේ අයිතිය උල්ලංඝනය කළ නොහැකි බවත් ප්‍රකාශ කළේය."),
    q(T, "අමෙරිකානු නිදහස් සටන අවසන් කරමින් බ්‍රිතාන්‍යය විසින් අමෙරිකා එක්සත් ජනපදයේ ස්වාධීනත්වය නිල වශයෙන් පිළිගත් ගිවිසුම කුමක්ද?", "1783 පැරිස් ගිවිසුම (Treaty of Paris)", "ලන්ඩන් ගිවිසුම", "වර්සායිල්ස් ගිවිසුම", "වොෂින්ටන් ගිවිසුම", "මෙම ගිවිසුමෙන් පසු ලොව ප්‍රථම ලිඛිත ආණ්ඩුක්‍රම ව්‍යවස්ථාව සහිත ප්‍රජාතන්ත්‍රවාදී සමූහාණ්ඩුව බිහිවිය."),
    q(T, "අමෙරිකා එක්සත් ජනපදයේ ප්‍රථම ජනාධිපතිවරයා ලෙස තේරී පත් වූයේ කවුද?", "ජෝර්ජ් වොෂින්ටන්", "තෝමස් ජෙෆර්සන්", "ජෝන් ඇඩම්ස්", "බෙන්ජමින් ෆ්‍රෑන්ක්ලින්", "ඇමරිකානු නිදහසේ පියා ලෙස සැලකෙන වොෂින්ටන් අමෙරිකාවේ ප්‍රථම ජනාධිපතිවරයා විය."),
    q(T, "ක්‍රි.ව. 1789 දී ආරම්භ වූ ප්‍රංශ විප්ලවයට (French Revolution) ආසන්නම හේතුව කුමක්ද?", "දැඩි මූල්‍ය අර්බුදය, සාගතය සහ තෙවන පන්තිය මත පමණක් බදු බර පැටවීම", "විදේශ ආක්‍රමණයක් සිදුවීම", "ආගමික යුද්ධයක් හටගැනීම", "කාර්මික වර්ජනයක්", "ප්‍රංශයේ ජනගහනයෙන් 98%ක් වූ සාමාන්‍ය ජනයා සියලු බදු ගෙවද්දී රදළයන් හා පූජකයන් සුඛෝපභෝගීව ජීවත් විය."),
    q(T, "ප්‍රංශ විප්ලවය සිදුවන සමයේ ප්‍රංශයේ රජකළ පාලකයා සහ ඔහුගේ බිසව කවුද?", "දහසයවන ලුවී රජු සහ මාරි ඇන්ටොයිනට් රැජින", "දහහතරවන ලුවී", "නැපෝලියන් බොනපාට්", "පළමුවන චාල්ස්", "අකාර්යක්ෂම හා අත්තනෝමතික පාලනයක් ගෙන ගිය දහසයවන ලුවී රජු ජනතා විරෝධයට ලක්විය."),
    q(T, "ප්‍රංශ විප්ලවයට පෙර ප්‍රංශ සමාජය බෙදී තිබූ ප්‍රධාන තට්ටු (එස්ටේට්) තුන මොනවාද?", "පූජක පන්තිය (පළමු), වංශවතුන් (දෙවන) සහ සාමාන්‍ය ජනයා (තෙවන පන්තිය)", "රජවරුන්, නයිට්වරුන් හා වහලුන්", "වෙළෙන්දන්, ගොවීන් හා කම්කරුවන්", "ධනවතුන් හා දුප්පතුන් පමණක්", "පළමු හා දෙවන පන්ති බදු ගෙවීමෙන් නිදහස්ව තිබූ අතර තුන්වන පන්තිය අධික බදු බරින් පීඩා වින්දේය."),
    q(T, "ප්‍රංශ විප්ලවයට බුද්ධිමය මඟපෙන්වීම ලබාදුන් ප්‍රංශ දාර්ශනිකයන් තිදෙනා කවුද?", "වෝල්ටෙයාර්, රූසෝ සහ මොන්ටෙස්ක්‍යු", "ප්ලේටෝ, ඇරිස්ටෝටල් හා සොක්‍රටීස්", "මාක්ස්, ලෙනින් හා එංගල්ස්", "ලොක්, හොබ්ස් හා ස්මිත්", "මානව නිදහස, සමානාත්මතාවය හා බලය බෙදීමේ න්‍යාය ඔවුන් සිය කෘති මගින් සමාජගත කළහ."),
    q(T, "ජීන් ජැක් රූසෝ (Jean-Jacques Rousseau) විසින් රචිත සුප්‍රකට දේශපාලන කෘතිය කුමක්ද?", "සමාජ සම්මුතිය (The Social Contract)", "නීතියේ ආත්මය", "යුතෝපියාව", "කුමාරයා", "'මිනිසා උපදින්නේ නිදහස්වය, නමුත් සෑම තැනකම ඔහු දම්වැල්වලින් බැඳී ඇත' යන්න රූසෝගේ ප්‍රකට කියමනකි."),
    q(T, "ආණ්ඩුවක බලතල ව්‍යවස්ථාදායකය, විධායකය සහ අධිකරණය ලෙස එකිනෙකින් වෙන් කළ යුතු බවට 'බලය බෙදීමේ න්‍යාය' ඉදිරිපත් කළේ කවුද?", "මොන්ටෙස්ක්‍යු (Montesquieu - 'නීතියේ ආත්මය' කෘතියෙන්)", "වෝල්ටෙයාර්", "රූසෝ", "මැකියාවෙලි", "ප්‍රජාතන්ත්‍රවාදී පාලනයකදී ඒකාධිපතිත්වය වැළැක්වීමට බලය බෙදීමේ මූලධර්මය මොන්ටෙස්ක්‍යු නිර්දේශ කළේය."),
    q(T, "ක්‍රි.ව. 1789 ජූලි 14 වන දින ප්‍රංශ විප්ලවවාදීන් විසින් බිඳ දමා විනාශ කරන ලද රාජකීය බලකොටුව හා බන්ධනාගාරය කුමක්ද?", "බැස්ටීල බලකොටුව (The Bastille)", "වර්සායිල්ස් මාලිගය", "නෝත්‍රඩෑම් දෙව්මැදුර", "ලූවර් මාලිගය", "රාජකීය කුරිරු මර්දනයේ හා ඒකාධිපතිත්වයේ සංකේතය වූ බැස්ටීලය බිඳ දැමීම විප්ලවයේ ආරම්භය සනිටුහන් කළේය."),
    q(T, "ප්‍රංශ විප්ලවයේ අමරණීය ප්‍රධාන තේමා පාඨය (සටන් පාඨය) වූයේ කුමක්ද?", "නිදහස, සමානාත්මතාවය, සහෝදරත්වය (Liberty, Equality, Fraternity)", "සාමය, පාන් සහ ඉඩම්", "නියෝජනයක් නැතිනම් බදු නැත", "එක්සත්කම ශක්තියයි", "මෙම උදාර සංකල්පය මුළු ලෝකයේම ප්‍රජාතන්ත්‍රවාදී අයිතිවාසිකම් සංවර්ධනයට මඟපෑදීය."),
    q(T, "ප්‍රංශ ජාතික සභාව විසින් 1789 දී සම්මත කරන ලද ඓතිහාසික මානව හිමිකම් ලියවිල්ල කුමක්ද?", "මිනිසාගේ සහ පුරවැසියාගේ අයිතිවාසිකම් පිළිබඳ ප්‍රකාශනය", "මැග්නා කාර්ටා", "බිල් ඔෆ් රයිට්ස්", "හේබියස් කෝපස්", "මිනිසුන් නිදහස් හා සමාන අයිතිවාසිකම් ඇතිව උපදින බවත් අදහස් ප්‍රකාශ කිරීමේ නිදහස අයිතියක් බවත් ප්‍රකාශ කළේය."),
    q(T, "ප්‍රංශ විප්ලවය සමයේ දහසයවන ලුවී රජු සහ මාරි ඇන්ටොයිනට් රැජින මරා දැමීමට යොදාගත් උපකරණය කුමක්ද?", "ගිලටීනය (Guillotine)", "එල්ලුම් ගස", "වෙඩි තැබීම", "විෂ දීම", "හිස ගසා දැමීම සඳහා විශේෂයෙන් නිර්මාණය කරන ලද ගිලටීනයෙන් රජු හා රැජින මරා දැමිණි."),
    q(T, "ප්‍රංශ විප්ලවයේ 'භීෂණ පාලන සමය' (Reign of Terror) මෙහෙයවූ ජැකොබින් නායකයා කවුද?", "මැක්සිමිලියන් රොබෙස්පියර් (Maximilien Robespierre)", "නැපෝලියන්", "ඩැන්ටන්", "මාරා", "විප්ලවයේ නාමයෙන් විරුද්ධවාදීන් දහස් ගණනක් ගිලටීනයට යැවූ රොබෙස්පියර් අවසානයේදී තමාද ගිලටීනයෙන්ම මරුමුවට පත්විය."),
    q(T, "ප්‍රංශ විප්ලවයේ අවුල් සහගත තත්ත්වය සමනය කරමින් ප්‍රංශයේ බලය අල්ලා ගෙන පසුව ප්‍රංශයේ අධිරාජ්‍යයා බවට පත් වූයේ කවුද?", "නැපෝලියන් බොනපාට් (Napoleon Bonaparte)", "දහඅටවන ලුවී", "රොබෙස්පියර්", "වොලන්ටයින්", "යුද හමුදා සෙන්පතියෙකු වූ නැපෝලියන් මුළු යුරෝපයම පාහේ ජය ගනිමින් නැපෝලියන් නීති සංග්‍රහය හඳුන්වා දුන්නේය."),
    q(T, "ක්‍රි.ව. 1917 දී රුසියාවේ සිදුවූ 'රුසියානු විප්ලවය' මෙහෙයවූ ප්‍රධාන සමාජවාදී පක්ෂය කුමක්ද?", "බොල්ෂෙවික් පක්ෂය (Bolshevik Party)", "මෙන්ෂෙවික් පක්ෂය", "නාසි පක්ෂය", "ෆැසිස්ට් පක්ෂය", "ව්ලැදිමීර් ලෙනින්ගේ නායකත්වයෙන් යුත් බොල්ෂෙවික්වරු ලොව ප්‍රථම කොමියුනිස්ට් රාජ්‍යය පිහිටුවූහ."),
    q(T, "රුසියානු විප්ලවය සිදුවන සමයේ රුසියාව පාලනය කළ අවසාන සාර් රජු කවුද?", "දෙවන නිකොලස් සාර් රජු (Tsar Nicholas II)", "පීටර් ද ග්‍රේට්", "ඇලෙක්සැන්ඩර්", "පළමුවන නිකොලස්", "රොමානොෆ් රාජවංශයේ 300 වසරක ඒකාධිපති සාර් පාලනය 1917 විප්ලවයෙන් අතුගා දැමිණි."),
    q(T, "ක්‍රි.ව. 1917 ඔක්තෝබර් විප්ලවයේදී බොල්ෂෙවික්වරුන් ජනතාව අතරට ගෙන ගිය ප්‍රධාන සටන් පාඨය කුමක්ද?", "සාමය, පාන් සහ ඉඩම් (Peace, Bread, Land)", "නිදහස, සමානාත්මතාවය", "රජුට මරණය", "යුද්ධය ජය ගනිමු", "පළමු ලෝක යුද්ධයෙන් ඉවත්වීම (සාමය), සාගතය නිමා කිරීම (පාන්) හා ගොවීන්ට ඉඩම් බෙදා දීම මින් පොරොන්දු විය."),
    q(T, "රුසියානු විප්ලවයේ ප්‍රධාන නායකයා මෙන්ම සෝවියට් සංගමයේ ප්‍රථම නායකයා වූයේ කවුද?", "ව්ලැදිමීර් ලෙනින් (Vladimir Lenin)", "ජෝසප් ස්ටාලින්", "ලියොන් ට්‍රොට්ස්කි", "කෲෂෙව්", "මාක්ස්වාදී දර්ශනය ප්‍රායෝගික රාජ්‍ය පාලනයකට පෙරළූ ලෙනින් සෝවියට් සමාජවාදී සමූහාණ්ඩු සංගමය (USSR) පිහිටුවීය."),
    q(T, "රුසියානු විප්ලවයෙන් පසු පිහිටුවන ලද ලොව ප්‍රථම සමාජවාදී රාජ්‍යය හැඳින්වූයේ කුමන නමින්ද?", "සෝවියට් සංගමය හෙවත් සෝවියට් සමාජවාදී සමූහාණ්ඩු සංගමය (USSR)", "රුසියානු අධිරාජ්‍යය", "නැගෙනහිර සමූහාණ්ඩුව", "යුරේසියානු සංගමය", "1922 දී නිල වශයෙන් පිහිටුවන ලද සෝවියට් සංගමය 20 වන සියවසේ ලෝක බලවතෙකු බවට පත්විය."),
    q(T, "යුරෝපීය පුනරුදය, කාර්මික විප්ලවය හා ලෝක විප්ලවයන් මගින් මානව ඉතිහාසයට කළ පොදු බලපෑම කුමක්ද?", "මධ්‍යතන වැඩවසම් ක්‍රමය බිඳවැටී විද්‍යාත්මක, ප්‍රජාතන්ත්‍රවාදී හා නූතන කාර්මික ලෝකයක් බිහිවීම", "ලෝකය අඳුරු යුගයකට ඇද වැටීම", "සියලු රාජ්‍යයන් විනාශ වීම", "තාක්ෂණය නැවතීම", "මානව හිමිකම්, නිදහස් චින්තනය, නූතන විද්‍යාව හා කර්මාන්ත ලොව පුරා ප්‍රචලිත විය."),
    q(T, "යුරෝපීය පුනරුදයේදී බිහිවූ 'මානවවාදය' (Humanism) යන සංකල්පයේ මූලික හරය කුමක්ද?", "මරණින් මතු ජීවිතය වෙනුවට මෙලොව ජීවිතය, මිනිසාගේ හැකියාවන් හා ගෞරවය අගය කිරීම", "දේව ධර්මය පමණක් ඉගෙනීම", "ලෞකික සැප සම්පත් මුළුමනින්ම ප්‍රතික්ෂේප කිරීම", "රජවරුන්ගේ දේවත්ව බලතල පිළිගැනීම", "මධ්‍යතන යුගයේ පැවති ආගමික කේන්ද්‍රීය දැක්ම වෙනුවට මිනිසා සහ ඔහුගේ ලෞකික යහපැවැත්ම ප්‍රමුඛ කරගත් චින්තනය මානවවාදයයි."),
    q(T, "පුනරුද සමයේ ඉතාලියේ ෆ්ලෝරන්ස් නුවර පාලනය කරමින් කලාවට සහ සාහිත්‍යයට අනුග්‍රහය දැක්වූ ධනවත් පවුල කවුරුන්ද?", "මෙඩිසි පවුල (Medici Family)", "හැප්ස්බර්ග් පවුල", "බෝර්බන් පවුල", "ටියුඩර් පවුල", "ලොරෙන්සෝ ද මෙඩිසි ඇතුළු මෙඩිසි පවුල පුනරුද කලාකරුවන්ට දැක්වූ අනුග්‍රහය ෆ්ලෝරන්ස් නගරය පුනරුදයේ කේන්ද්‍රස්ථානය වීමට හේතු විය."),
    q(T, "මයිකල් ආන්ජලෝ විසින් රෝමයේ සිස්ටයින් දේවස්ථානයේ සිවිලිමේ අඳින ලද සුප්‍රකට බිතු සිතුවම කුමක්ද?", "ආදම්ගේ නිර්මාණය (The Creation of Adam)", "මොනාලිසා", "අවසාන රාත්‍රී භෝජන සංග්‍රහය", "ඇතැන්ස් ඇකඩමිය", "ක්‍රිස්තියානි බයිබලයේ උත්පත්ති කතාව නිරූපණය වන පරිදි දෙවියන් වහන්සේ සහ ආදම්ගේ ඇඟිලි ස්පර්ශ වන අයුරු දැක්වෙන නිර්මාණයකි."),
    q(T, "මයිකල් ආන්ජලෝ විසින් කිරිගරුඬෙන් නෙළන ලද අසමසම මූර්ති නිර්මාණ දෙකක් වන්නේ කවරේද?", "ඩේවිඩ් සහ පියෙටා (David and Pieta)", "මොනාලිසා සහ මැඩෝනා", "සිකුරු ප්‍රතිමාව සහ අපොලෝ", "ලැඕකූන් සහ බුද්ධ ප්‍රතිමාව", "ඩේවිඩ් ප්‍රතිමාව සහ මියගිය යේසුස් වහන්සේ උකුලේ හොවාගත් මරියා මවුගේ පියෙටා ප්‍රතිමාව ලෝක ප්‍රකට මූර්ති නිර්මාණයන්ය."),
    q(T, "ඉතාලි පුනරුද යුගයේ විසූ සුප්‍රකට ගෘහ නිර්මාණ ශිල්පියෙකු වූ ෆිලිප්පෝ බෲනලෙස්කි (Brunelleschi) ගේ අග්‍රගන්‍ය නිර්මාණය කුමක්ද?", "ෆ්ලෝරන්ස් නුවර ආසන දෙව්මැදුරේ මහා ගෝලාකාර වහලය (Duomo of Florence)", "ශාන්ත පීතර බැසිලිකාව", "කොලෝසියම", "පැන්තියන් දෙව්මැදුර", "මධ්‍යතන යුගයෙන් පසු අභ්‍යන්තර බර රඳවන ආරුක්කු නොමැතිව ඉදිකළ විශාලතම ගඩොල් ගෝලාකාර වහලය මෙයයි."),
    q(T, "පුනරුද සමයේ ලියවුණු 'ඩෙකැමරන්' (Decameron) නම් විශිෂ්ට කතා එකතුවේ කතුවරයා කවුද?", "ජියෝවානි බොකෑචියෝ (Giovanni Boccaccio)", "ප්‍රැන්සිස්කෝ පෙට්‍රාක්", "ඩැන්ටේ අලිගියෙරි", "මැකියාවෙලි", "ෆ්ලෝරන්ස් නගරයේ පැතිර ගිය මහා කළු මරණය (වසංගතය) පසුබිම් කරගනිමින් තරුණ තරුණියන් පිරිසක් කියන කතා ඇතුළත් කෘතියකි."),
    q(T, "ස්පාඤ්ඤ ජාතික මිගෙල් ද සර්වාන්ටෙස් විසින් ලියන ලද ලොව ප්‍රථම නූතන නවකතාව ලෙස සැලකෙන කෘතිය කුමක්ද?", "දොන් කිහෝතේ (Don Quixote)", "දිව්‍ය ප්‍රහසනය", "යුතෝපියාව", "කැන්ටබරි කතා", "මධ්‍යතන යුගයේ නයිට්වරුන්ගේ මනඃකල්පිත ක්‍රියාකාරකම් උපහාසයට ලක්කරමින් රචිත විශ්ව සාහිත්‍ය නිර්මාණයකි."),
    q(T, "ඉංග්‍රීසි සාහිත්‍යයේ අසහාය නාට්‍යකරුවා වූ විලියම් ෂේක්ස්පියර්ගේ ඛේදාන්ත නාට්‍ය ත්‍රිත්වයක් වන්නේ කවරේද?", "හැම්ලට්, ඔතෙලෝ සහ මැක්බත්", "දොන් කිහෝතේ, ඩෙකැමරන්, යුතෝපියාව", "මොනාලිසා, ඩේවිඩ්, පියෙටා", "දිව්‍ය ප්‍රහසනය, කුමාරයා, පාරාදීසය", "ෂේක්ස්පියර්ගේ නාට්‍ය තුළ මානව හැඟීම්, තණ්හාව, වෛරය, ආදරය සහ ඛේදවාචකය ගැඹුරින් විශ්ලේෂණය කර ඇත."),
    q(T, "සූර්ය කේන්ද්‍රවාදී න්‍යාය ඔප්පු කිරීම සඳහා දුරේක්ෂය නිපදවා බ්‍රහස්පතිගේ චන්ද්‍රයන් නිරීක්ෂණය කළ විද්‍යාඥයා කවුද?", "ගැලීලියෝ ගැලිලි (Galileo Galilei)", "නිකොලස් කොපර්නිකස්", "අයිසැක් නිව්ටන්", "ජොහැන්නස් කෙප්ලර්", "ගැලීලියෝ විසින් දුරේක්ෂය මගින් චන්ද්‍රයාගේ කඳු, සූර්ය ලප සහ බ්‍රහස්පතිගේ උපග්‍රහයන් සොයාගනිමින් සම්ප්‍රදායික පෘථිවි කේන්ද්‍රවාදය බිඳ දැමීය."),
    q(T, "ග්‍රහලෝක සූර්යයා වටා ඉලිප්සාකාර කක්ෂවල භ්‍රමණය වන බවට ග්‍රහ චලිත නියම ඉදිරිපත් කළ තාරකා විද්‍යාඥයා කවුද?", "ජොහැන්නස් කෙප්ලර් (Johannes Kepler)", "ටයිකෝ බ්‍රාහේ", "ටොලමි", "ඇරිස්ටෝටල්", "කෙප්ලර්ගේ ග්‍රහ චලිත නියම ත්‍රිත්වය නූතන තාරකා විද්‍යාවේ පදනම දැමීය."),
    q(T, "ගුරුත්වාකර්ෂණ නියමය සහ චලිතය පිළිබඳ මූලික නියම තුන ඉදිරිපත් කරමින් භෞතික විද්‍යාවේ විප්ලවයක් කළ විද්‍යාඥයා කවුද?", "ශ්‍රීමත් අයිසැක් නිව්ටන් (Sir Isaac Newton)", "ඇල්බට් අයින්ස්ටයින්", "රොබට් බොයිල්", "මයිකල් ෆැරඩේ", "නිව්ටන්ගේ 'ප්‍රින්සිපියා මැතමැටිකා' කෘතිය නූතන සම්භාව්‍ය භෞතික විද්‍යාවේ පදනම තැබීය."),
    q(T, "මිනිස් සිරුරේ රුධිර සංසරණ පද්ධතිය පිළිබඳව නිවැරදි විද්‍යාත්මක සොයාගැනීම කළ වෛද්‍ය විද්‍යාඥයා කවුද?", "විලියම් හාවි (William Harvey)", "ඇන්ඩ්‍රියාස් විසාලියස්", "ලුවී පාස්චර්", "එඩ්වඩ් ජෙනර්", "විලියම් හාවි විසින් හෘදය වස්තුව රුධිරය පොම්ප කරන ආකාරය සහ රුධිර නාල හරහා සංසරණය වන ආකාරය විස්තර කළේය."),
    q(T, "මිනිස් සිරුර කපා පරීක්ෂා කරමින් නූතන ව්‍යවච්ඡේද විද්‍යාවේ (Anatomy) පියා ලෙස සලකනු ලබන්නේ කවුද?", "ඇන්ඩ්‍රියාස් විසාලියස් (Andreas Vesalius)", "හිපොක්‍රටීස්", "ගැලන්", "ඇරිස්ටෝටල්", "විසාලියස්ගේ 'ද හියුමනි කෝපොරිස් ෆැබ්රිකා' කෘතිය මිනිස් සිරුරේ අභ්‍යන්තර ව්‍යුහය පිළිබඳ මධ්‍යතන මත නිවැරදි කළේය."),
    q(T, "පෘතුගාලයේ නාවික පාසලක් පිහිටුවා භූගෝලීය ගවේෂණ සඳහා මඟපෙන්වූ පාලකයා කවුද?", "හෙන්රි නාවික කුමාරයා (Prince Henry the Navigator)", "මැනුවෙල් රජු", "ජෝන් රජු", "පෙඩ්රෝ කුමාරයා", "හෙන්රි කුමාරයාගේ නාවික විද්‍යාලය හා සිතියම් විද්‍යා දියුණුව පෘතුගීසි ගවේෂණ රැල්ල ආරම්භ කිරීමට හේතු විය."),
    q(T, "ක්‍රි.ව. 1488 දී අප්‍රිකා මහද්වීපයේ දකුණු කෙළවරට (සුබපැතුම් තුඩුව) ළඟා වූ පෘතුගීසි නාවිකයා කවුද?", "බර්තොලමියු ඩයස් (Bartolomeu Dias)", "ක්‍රිස්ටෝෆර් කොලම්බස්", "ෆර්ඩිනන්ඩ් මැගලන්", "ඇමරිගෝ වෙස්පුචි", "කුණාටු සහිත අප්‍රිකානු දකුණු තුඩුව 'කුණාටු තුඩුව' ලෙස නම් කළ අතර පසුව පෘතුගාල රජු එය 'සුබපැතුම් තුඩුව' (Cape of Good Hope) ලෙස නම් කළේය."),
    q(T, "ක්‍රි.ව. 1492 දී ස්පාඤ්ඤයේ අනුග්‍රහයෙන් බටහිර දෙසට යාත්‍රා කර ඇමරිකානු මහද්වීපය අසල බහමාස් දූපත්වලට ළඟා වූ නාවිකයා කවුද?", "ක්‍රිස්ටෝෆර් කොලම්බස් (Christopher Columbus)", "මාර්කෝ පෝලෝ", "ජෝන් කැබට්", "කෝටේස්", "ඉන්දියාවට නව මුහුදු මාර්ගයක් සෙවීමේ අරමුණින් ගමන් කළ කොලම්බස් නව ලෝකය (ඇමරිකාව) සොයාගත්තේය."),
    q(T, "ඇමරිකාව යනු ආසියාවේ කොටසක් නොව වෙනම නව මහද්වීපයක් බව මුලින්ම තහවුරු කළ නාවිකයා කවුද?", "ඇමරිගෝ වෙස්පුචි (Amerigo Vespucci)", "කොලම්බස්", "ඩයස්", "මැගලන්", "ඇමරිගෝ වෙස්පුචිගේ නම මුල්කරගෙන පසුව ජර්මානු සිතියම් ශිල්පී මාර්ටින් වෝල්ඩ්සීමියුලර් විසින් මෙම භූමිය 'ඇමරිකාව' ලෙස නම් කරන ලදී."),
    q(T, "ලොව වටා මුහුදෙන් යාත්‍රා කළ ප්‍රථම නාවික ගවේෂණය මෙහෙයවූ පෘතුගීසි ජාතික නාවිකයා කවුද?", "ෆර්ඩිනන්ඩ් මැගලන් (Ferdinand Magellan)", "ෆ්‍රැන්සිස් ඩ්‍රේක්", "ජේම්ස් කුක්", "හෙන්රි හඩ්සන්", "මැගලන් පිලිපීනයේදී මියගියද ඔහුගේ 'වික්ටෝරියා' නෞකාව ජුවාන් සෙබස්තියන් එල්කානෝගේ නායකත්වයෙන් පෘථිවිය වටා සාර්ථකව යාත්‍රා කර ලොව ගෝලාකාර බව ඔප්පු කළේය."),
    q(T, "ක්‍රි.ව. 1494 දී ස්පාඤ්ඤය හා පෘතුගාලය අතර නව ලෝකයේ ඉඩම් බෙදා ගැනීම සඳහා අත්සන් තැබූ ගිවිසුම කුමක්ද?", "ටෝර්ඩසිලාස් ගිවිසුම (Treaty of Tordesillas)", "පැරිස් ගිවිසුම", "වර්සායිල්ස් ගිවිසුම", "වෙස්ට්ෆේලියා ගිවිසුම", "හයවන ඇලෙක්සැන්ඩර් පාප්තුමාගේ මැදිහත්වීමෙන් අත්ලාන්තික් සාගරය මැදින් දේශසීමා රේඛාවක් ඇඳ ස්පාඤ්ඤයට හා පෘතුගාලයට භූමි ප්‍රදේශ බෙදා දෙන ලදී."),
    q(T, "මෙක්සිකෝවේ විසූ ඇස්ටෙක් (Aztec) ශිෂ්ටාචාරය ආක්‍රමණය කර යටත් කරගත් ස්පාඤ්ඤ ජාතික ආක්‍රමණිකයා (Conquistador) කවුද?", "හර්නාන් කෝටේස් (Hernan Cortes)", "ෆ්‍රැන්සිස්කෝ පිසාරෝ", "පේද්‍රෝ අල්වාරෙස් කබ්රාල්", "පොන්සේ ද ලියොන්", "කෝටේස් විසින් ඇස්ටෙක් අධිරාජ්‍යයා වූ මොන්ටෙසූමා ඝාතනය කර මෙක්සිකෝව ස්පාඤ්ඤ යටත්විජිතයක් බවට පත් කරන ලදී."),
    q(T, "දකුණු ඇමරිකාවේ පේරු රාජ්‍යයේ පැවති ඉන්කා (Inca) ශිෂ්ටාචාරය විනාශ කර යටත් කරගත් ස්පාඤ්ඤ ජාතිකයා කවුද?", "ෆ්‍රැන්සිස්කෝ පිසාරෝ (Francisco Pizarro)", "හර්නාන් කෝටේස්", "මැගලන්", "ඩොමිනිකෝ", "පිසාරෝ විසින් ඉන්කා පාලක අටහුඅල්පා රවටා මරා දමා අතිවිශාල රන් රිදී සම්භාරයක් කොල්ලකන ලදී."),
    q(T, "කාර්මික විප්ලවයේදී රෙදි විවීමේ කාර්යක්ෂමතාව ඉහළ නැංවූ 'දුවන නඩාව' (Flying Shuttle) නිපදවූයේ කවුද?", "ජෝන් කේ (John Kay)", "ජේම්ස් හාග්‍රීව්ස්", "රිචඩ් ආර්ක්රයිට්", "එඩ්මන්ඩ් කාට්රයිට්", "1733 දී ජෝන් කේ විසින් දුවන නඩාව නිපදවීම නිසා රෙදි විවීමේ වේගය දෙගුණයකින් වැඩි විය."),
    q(T, "නූල් කැටීම වේගවත් කිරීම සඳහා 'ස්පිනින් ජෙනී' (Spinning Jenny) නම් යන්ත්‍රය නිපදවූ ඉංග්‍රීසි ජාතිකයා කවුද?", "ජේම්ස් හාග්‍රීව්ස් (James Hargreaves)", "ජෝන් කේ", "රිචඩ් ආර්ක්රයිට්", "සැමුවෙල් ක්‍රොම්ප්ටන්", "එක්වර නූල් කෙන්දකට වඩා කැටිය හැකි මෙම යන්ත්‍රය රෙදිපිළි කර්මාන්තයේ දැවැන්ත පෙරළියක් ඇති කළේය."),
    q(T, "ජල බලයෙන් ක්‍රියා කරන 'ජල රාමුව' (Water Frame) නූල් කටින යන්ත්‍රය නිපදවමින් කර්මාන්තශාලා ක්‍රමයට මග පෑදුවේ කවුද?", "රිචඩ් ආර්ක්රයිට් (Richard Arkwright)", "ජේම්ස් වොට්", "ජෝර්ජ් ස්ටීවන්සන්", "හම්ෆ්‍රි ඩේවි", "ජල බලය උපයෝගී කරගත් නිසා ගංගා අසල විශාල කපු මෝල් බිහිවීමට මෙය හේතු විය."),
    q(T, "නූල් කැටීමේ 'මියුල්' (Spinning Mule) යන්ත්‍රය නිපදවා ශක්තිමත් මෙන්ම සිහින් උසස් නූල් නිෂ්පාදනයට මග පෑදුවේ කවුද?", "සැමුවෙල් ක්‍රොම්ප්ටන් (Samuel Crompton)", "ජෝන් කේ", "හාග්‍රීව්ස්", "ආර්ක්රයිට්", "හාග්‍රීව්ස්ගේ ජෙනී යන්ත්‍රයේ සහ ආර්ක්රයිට්ගේ ජල රාමුවේ ගුණාංග එකතු කර මියුල් යන්ත්‍රය නිර්මාණය කරන ලදී."),
    q(T, "කාර්මික විප්ලවයේදී වාෂ්ප බලයෙන් ක්‍රියාත්මක වන ප්‍රථම 'බලවේග රෙදි වියනය' (Power Loom) නිපදවූයේ කවුද?", "එඩ්මන්ඩ් කාට්රයිට් (Edmund Cartwright)", "ජේම්ස් වොට්", "ජෝර්ජ් ස්ටීවන්සන්", "තෝමස් නිව්කොමන්", "මෙම යන්ත්‍රය මගින් රෙදි විවීම මුළුමනින්ම යාන්ත්‍රිකරණය වී දැවැන්ත කර්මාන්තශාලා බිහි විය."),
    q(T, "යකඩ උණු කිරීමේදී අඟුරු වෙනුවට ගල්අඟුරු (Coke) යොදාගැනීමේ ක්‍රමය හඳුන්වා දුන් බ්‍රිතාන්‍ය කාර්මිකයා කවුද?", "ඒබ්‍රහම් ඩාර්බි (Abraham Darby)", "හෙන්රි කෝට්", "හෙන්රි බෙසමර්", "ජේම්ස් වොට්", "ගල්අඟුරු භාවිතයෙන් උසස් තත්ත්වයේ වාත්තු යකඩ විශාල පරිමාණයෙන් නිපදවීමට හැකි විය."),
    q(T, "යකඩ ලාභදායී ලෙස හා කාර්යක්ෂමව වානේ (Steel) බවට පත්කිරීමේ ක්‍රමවේදය සොයාගත් ඉංජිනේරුවා කවුද?", "හෙන්රි බෙසමර් (Henry Bessemer)", "ඒබ්‍රහම් ඩාර්බි", "ජෝර්ජ් ස්ටීවන්සන්", "තෝමස් ටෙල්ෆර්ඩ්", "බෙසමර් පරිවර්තකය (Bessemer Process) මගින් වානේ යුගය ආරම්භ වූ අතර දුම්රිය මාර්ග සහ පාලම් ඉදිකිරීමට මග පෑදිණි."),
    q(T, "ගල්අඟුරු පතල් කම්කරුවන්ගේ ආරක්ෂාව වෙනුවෙන් 'ආරක්ෂිත ලාම්පුව' (Safety Lamp) නිපදවූ විද්‍යාඥයා කවුද?", "ශ්‍රීමත් හම්ෆ්‍රි ඩේවි (Sir Humphry Davy)", "මයිකල් ෆැරඩේ", "ජේම්ස් වොට්", "රොබට් බොයිල්", "පතල් තුළ ඇති මීතේන් වායුවට ගිනි නොඇවිලෙන පරිදි දැල් ආවරණය සහිත ඩේවි ලාම්පුව පතල් අනතුරු බෙහෙවින් අඩු කළේය."),
    q(T, "කාර්මික විප්ලවයේදී මහා මාර්ග ඉදිකිරීමේ විප්ලවීය ක්‍රමයක් හඳුන්වා දුන් ඉංජිනේරුවා කවුද?", "ජෝන් මැකඩම් (John McAdam)", "තෝමස් ටෙල්ෆර්ඩ්", "ජෝර්ජ් ස්ටීවන්සන්", "ජේම්ස් බ්‍රින්ඩ්ලි", "කුඩා තලා දැමූ ගල් ස්ථර මගින් ජලය බැසයන සුමට මතුපිටක් සහිත පාරවල් තැනීමේ 'මැකඩම් ක්‍රමය' ලොව පුරා ප්‍රචලිත විය."),
    q(T, "බ්‍රිතාන්‍යයේ කාර්මික නිෂ්පාදන ප්‍රවාහනය සඳහා ඇළ මාර්ග පද්ධති (Canals) ඉදිකිරීමේ ප්‍රමුඛයා වූයේ කවුද?", "ජේම්ස් බ්‍රින්ඩ්ලි (James Brindley)", "ජෝර්ජ් ස්ටීවන්සන්", "මැකඩම්", "බෙසමර්", "බ්‍රිජ්වෝටර් ආදිපාදවරයා වෙනුවෙන් වෝර්ස්ලි සිට මැන්චෙස්ටර් දක්වා පළමු ඇළ ඉදිකිරීම බ්‍රිතාන්‍යයේ ඇළ මාර්ග යුගය ආරම්භ කළේය."),
    q(T, "කාර්මික විප්ලවයේ ප්‍රතිඵලයක් ලෙස බ්‍රිතාන්‍යයේ ඇතිවූ නාගරීකරණයේ ලක්ෂණයක් නොවන්නේ කුමක්ද?", "ග්‍රාමීය ජනගහනය වේගයෙන් ඉහළ ගොස් නගර පාළුවට යාම", "මැන්චෙස්ටර්, බර්මිංහැම් වැනි නව කාර්මික නගර බිහිවීම", "නගරවල සනීපාරක්ෂක ගැටලු සහ මුඩුක්කු බිහිවීම", "කම්හල් ආශ්‍රිතව කම්කරු පන්තියක් සංකේන්ද්‍රණය වීම", "කාර්මික විප්ලවය නිසා සිදුවූයේ ගම්බද ජනයා කම්හල් රැකියා සොයා විශාල වශයෙන් නගර කරා සංක්‍රමණය වීමයි."),
    q(T, "කාර්මික විප්ලව සමයේ කම්හල්වල සේවය කළ ළමා හා කාන්තා ශ්‍රමිකයන්ගේ සේවා තත්ත්වයන් වැඩිදියුණු කිරීමට සම්මත කළ පනත් මොනවාද?", "කර්මාන්තශාලා පනත් (Factory Acts)", "දුගී පනත", "චාර්ටර් පනත", "වැඩවසම් පනත", "දෛනික සේවා පැය ගණන සීමා කිරීම සහ ළමුන් සේවයේ යෙදවීම නියාමනය කිරීමට බ්‍රිතාන්‍ය පාර්ලිමේන්තුව කර්මාන්තශාලා පනත් සම්මත කළේය."),
    q(T, "18 වන සියවසේ උතුරු ඇමරිකාවේ පිහිටුවා තිබූ බ්‍රිතාන්‍ය යටත්විජිත සංඛ්‍යාව කීයද?", "13 ක්", "10 ක්", "15 ක්", "20 ක්", "අත්ලාන්තික් වෙරළ තීරයේ පිහිටි ජෝර්ජියා, වර්ජිනියා, මැසචුසෙට්ස් ඇතුළු ජනපද 13 නිදහස් සටන මෙහෙයවීය."),
    q(T, "ඇමරිකානු නිදහස් සටනට මග පෑදූ 'නියෝජනයක් නැතිනම් බදු නැත' (No taxation without representation) යන සටන් පාඨය එල්ල වූයේ කාටද?", "බ්‍රිතාන්‍ය පාර්ලිමේන්තුවට", "ප්‍රංශ රජුට", "ස්පාඤ්ඤ පාලකයන්ට", "ඇමරිකානු ආදිවාසීන්ට", "බ්‍රිතාන්‍ය පාර්ලිමේන්තුවේ ඇමරිකානුවන්ට නියෝජනයක් නොමැතිව ඔවුන් මත මුද්දර බදු සහ තේ බදු පැනවීමට එරෙහිව මෙම සටන් පාඨය නැගිණි."),
    q(T, "ක්‍රි.ව. 1773 දී ඇමරිකානු විරෝධතාකරුවන් බොස්ටන් වරායේදී තේ පෙට්ටි මුහුදට විසි කිරීමේ සිද්ධිය හඳුන්වන්නේ කුමන නමින්ද?", "බොස්ටන් තේ සාදය (Boston Tea Party)", "බොස්ටන් සංහාරය", "ලෙක්සිංටන් සටන", "යෝර්ක්ටවුන් යටත්වීම", "තේ බද්දට විරෝධය පාමින් රතු ඉන්දියානුවන් සේ වෙස්වලාගත් පිරිසක් නැව් තුනක තිබූ තේ පෙට්ටි මුහුදට හෙළූහ."),
    q(T, "ඇමරිකානු විමුක්ති හමුදාවේ ප්‍රධාන සේනාධිපති ලෙස පත්වෙමින් නිදහස් සටන මෙහෙයවූ නායකයා කවුද?", "ජෝර්ජ් වොෂිංටන් (George Washington)", "තෝමස් ජෙෆර්සන්", "බෙන්ජමින් ෆ්‍රැන්ක්ලින්", "ජෝන් ඇඩම්ස්", "වොෂිංටන්ගේ විශිෂ්ට නායකත්වය යටතේ ඇමරිකානු හමුදාව ලොව බලවත්ම බ්‍රිතාන්‍ය හමුදාව පරාජය කර නිදහස දිනාගත්හ."),
    q(T, "ක්‍රි.ව. 1776 ජූලි 4 වන දින ඇමරිකානු නිදහස් ප්‍රකාශනය (Declaration of Independence) කෙටුම්පත් කළ ප්‍රධාන නායකයා කවුද?", "තෝමස් ජෙෆර්සන් (Thomas Jefferson)", "ජෝර්ජ් වොෂිංටන්", "ඇලෙක්සැන්ඩර් හැමිල්ටන්", "ජේම්ස් මැඩිසන්", "ජීවිතය, නිදහස සහ සතුට ළඟා කරගැනීම සෑම මිනිසෙකුගේම අහිමි කළ නොහැකි අයිතිවාසිකම් බව මෙමගින් ප්‍රකාශ කෙරිණි."),
    q(T, "ඇමරිකානු නිදහස් සටනේදී බ්‍රිතාන්‍ය හමුදාව අවසන් වරට පරාජයට පත්වූ තීරණාත්මක සටන කුමක්ද?", "යෝර්ක්ටවුන් සටන 1781 (Battle of Yorktown)", "ලෙක්සිංටන් සටන", "බන්කර් හිල් සටන", "සරටෝගා සටන", "කොන්වොලිස් සාමිවරයා ප්‍රමුඛ බ්‍රිතාන්‍ය හමුදාව යෝර්ක්ටවුන්හිදී ඇමරිකානු සහ ප්‍රංශ හමුදා හමුවේ යටත් විය."),
    q(T, "ඇමරිකා එක්සත් ජනපදයේ ප්‍රථම ජනාධිපතිවරයා බවට පත්වූයේ කවුද?", "ජෝර්ජ් වොෂිංටන් (George Washington)", "තෝමස් ජෙෆර්සන්", "ජෝන් ඇඩම්ස්", "ඒබ්‍රහම් ලින්කන්", "ඇමරිකානු ආණ්ඩුක්‍රම ව්‍යවස්ථාව යටතේ 1789 දී ඔහු නිතරඟයෙන් ප්‍රථම ජනාධිපතිවරයා ලෙස තේරී පත් විය."),
    q(T, "ප්‍රංශ විප්ලවයට පෙර ප්‍රංශ සමාජය බෙදා තිබූ ප්‍රධාන 'තන්ත්‍ර' (Estates) ත්‍රිත්වය මොනවාද?", "පූජක පක්ෂය, වංශවතුන් සහ සාමාන්‍ය ජනතාව", "රජු, රැජින සහ ඇමතිවරුන්", "ගොවීන්, කම්කරුවන් සහ වෙළඳුන්", "හමුදාව, නාවික හමුදාව සහ ගුවන් හමුදාව", "පළමු තන්ත්‍රය පූජකයන්ද, දෙවන තන්ත්‍රය වංශවතුන්ද වූ අතර සියලු බදු බර දැරූ 98% ක් වූ සාමාන්‍ය ජනයා තුන්වන තන්ත්‍රයට අයත් විය."),
    q(T, "ප්‍රංශ විප්ලවය ආරම්භ වන විට ප්‍රංශය පාලනය කළ බෝර්බන් රාජවංශයේ රජු සහ රැජින කවුරුන්ද?", "දහසයවන ලුවී රජු සහ මාරි ඇන්ටොයිනෙට් රැජින", "දහහතරවන ලුවී සහ ඈන් රැජින", "නැපෝලියන් සහ ජොසෆින්", "පළමුවන චාල්ස් සහ හෙන්රියාටා", "රජුගේ අදූරදර්ශී පාලනය සහ මාරි ඇන්ටොයිනෙට් රැජිනගේ අධික වියදම් රට දරුණු මූල්‍ය අර්බුදයකට ඇද දැමීය."),
    q(T, "ප්‍රංශ රජු විසින් වසර 175 කට පසු 1789 දී කැඳවන ලද නියෝජිත මණ්ඩලය කුමක්ද?", "රාජ්‍ය මන්ත්‍රණ සභාව (Estates-General)", "ජාතික මහා මණ්ඩලය", "සෙනෙට් සභාව", "පාර්ලිමේන්තුව", "බදු වැඩිකිරීම අනුමත කරවා ගැනීමට දහසයවන ලුවී රජුට එස්ටේට්ස් ජෙනරල් සභාව කැඳවීමට සිදුවිය."),
    q(T, "ප්‍රංශ විප්ලවයේදී තුන්වන තන්ත්‍රයේ නියෝජිතයන් නව ව්‍යවස්ථාවක් හදන තුරු විසිර නොයන බවට කළ දිවුරුම කුමක්ද?", "ටෙනිස් පිටියේ දිවුරුම (Tennis Court Oath)", "බැස්ටීල දිවුරුම", "වර්සායිල්ස් ප්‍රතිඥාව", "පැරිස් ප්‍රකාශනය", "රජු ඔවුන්ගේ රැස්වීම් ශාලාව වසා දැමූ විට අසල තිබූ ගෘහස්ථ ටෙනිස් පිටියකට රැස්වී ජාතික සභාව පිහිටුවා දිවුරුම් දුන්හ."),
    q(T, "ප්‍රංශ විප්ලවයේ සංකේතයක් වූ බැස්ටීල (Bastille) බන්ධනාගාරය ජනතාව විසින් බිඳ දැමූ ඓතිහාසික දිනය කුමක්ද?", "1789 ජූලි 14", "1789 මැයි 5", "1792 සැප්තැම්බර් 21", "1793 ජනවාරි 21", "රාජකීය කුරිරු පාලනයේ සංකේතයක් වූ බැස්ටීලය බිඳ දැමීම සමරමින් ප්‍රංශ ජාතික දිනය අදටත් ජූලි 14 සමරනු ලබයි."),
    q(T, "ප්‍රංශ විප්ලවය විසින් ලොවට දායාද කළ අමරණීය ප්‍රධාන තේමා පාඨය (Motto) කුමක්ද?", "නිදහස, සමානාත්මතාවය, සහෝදරත්වය (Liberte, Egalite, Fraternite)", "සාමය, පාන් සහ ඉඩම්", "නියෝජනයක් නැතිනම් බදු නැත", "එක්සත්කම ශක්තියයි", "මෙම මූලධර්ම ලොව පුරා මානව හිමිකම් සහ ප්‍රජාතන්ත්‍රවාදී ව්‍යාපාරයන්හි පදනම බවට පත්විය."),
    q(T, "ප්‍රංශ විප්ලව සමයේ විරුද්ධවාදීන්ගේ හිස් ගසා දැමීම සඳහා නිර්මාණය කරන ලද යාන්ත්‍රික උපකරණය කුමක්ද?", "ගිලටීනය (Guillotine)", "එල්ලුම් ගස", "විදුලි පුටුව", "තුවක්කු වෙඩි තැබීම", "ආචාර්ය ජෝසෆ් ඉග්නස් ගිලටින්ගේ යෝජනාවක් අනුව තැනූ මෙම උපකරණයෙන් දහසයවන ලුවී සහ මාරි ඇන්ටොයිනෙට් ඇතුළු දහස් ගණනක් මරා දැමිණි."),
    q(T, "නැපෝලියන් බොනපාට් විසින් යුරෝපය පුරා නීතියේ ආධිපත්‍යය හා සමානාත්මතාවය තහවුරු කරමින් සම්පාදනය කළ නීති මාලාව කුමක්ද?", "නැපෝලියන් නීති සංග්‍රහය (Napoleonic Code)", "ජස්ටීනියන් නීතිය", "හැමුරාබි නීතිය", "මැග්නා කාර්ටා", "නූතන සිවිල් නීති පද්ධතියට පදනම් වූ මෙම නීති සංග්‍රහය නැපෝලියන්ගේ වඩාත්ම කල්පවත්නා ජයග්‍රහණය ලෙස සැලකේ."),
    q(T, "නැපෝලියන් බොනපාට් අවසන් වරට පරාජය කර පිටුවහල් කරන ලද 1815 ඓතිහාසික සටන කුමක්ද?", "වෝටර්ලූ සටන (Battle of Waterloo)", "ට්‍රැෆල්ගාර් සටන", "ලයිප්සිග් සටන", "ඔස්ටර්ලිට්ස් සටන", "බෙල්ජියමේ වෝටර්ලූහිදී වෙලින්ටන් ආදිපාදවරයා සහ බ්ලූචර් ප්‍රමුඛ මිත්‍ර හමුදා හමුවේ නැපෝලියන් සම්පූර්ණයෙන්ම පරාජය විය."),
    q(T, "ක්‍රි.ව. 1905 දී සාර් රජුගේ මාලිගය ඉදිරිපිටදී සාමකාමී කම්කරුවන්ට වෙඩි තැබීමේ ඛේදනීය සිදුවීම හඳුන්වන්නේ කුමක් ලෙසද?", "ලේවැකි ඉරිදා (Bloody Sunday)", "රතු ඔක්තෝබරය", "ශීත ඍතු සංහාරය", "පීටර්ස්බර්ග් විරෝධය", "ජෝර්ජි ගැපොන් පියතුමා ප්‍රමුඛ කම්කරුවන්ගේ සාමකාමී පෙළපාලියට සාර් හමුදාව වෙඩි තැබීම 1905 රුසියානු විප්ලවයට මුල පිරීය."),
    q(T, "1917 පෙබරවාරි විප්ලවයෙන් සාර් රජු සිහසුන අත්හැරීමෙන් පසු පිහිටුවූ තාවකාලික ආණ්ඩුවේ නායකයා වූයේ කවුද?", "ඇලෙක්සැන්ඩර් කෙරෙන්ස්කි (Alexander Kerensky)", "ලෙනින්", "ට්‍රොට්ස්කි", "ස්ටාලින්", "කෙරෙන්ස්කිගේ තාවකාලික ආණ්ඩුව පළමු ලෝක යුද්ධය දිගටම කරගෙන යාමට තීරණය කිරීම නිසා ජනතා අප්‍රසාදයට පත්විය."),
    q(T, "ලෙනින් විසින් රුසියානු කොමියුනිස්ට් පක්ෂයේ ප්‍රචාරක පුවත්පත ලෙස පවත්වාගෙන ගිය සුප්‍රකට පුවත්පත කුමක්ද?", "ප්‍රව්ඩා (Pravda / සත්‍යය)", "ඉස්ක්‍රා", "ද ටයිම්ස්", "නිව්යෝක් ටයිම්ස්", "බොල්ෂෙවික් මතවාද කම්කරුවන් සහ ගොවීන් අතරට ගෙන යාමට ප්‍රව්ඩා පුවත්පත මගින් විශාල සේවයක් ඉටු විය."),
    q(T, "රුසියානු විප්ලවයෙන් පසු පළමු ලෝක යුද්ධයෙන් රුසියාව ඉවත් කරගැනීම සඳහා ජර්මනිය සමග අත්සන් කළ ගිවිසුම කුමක්ද?", "බ්‍රෙස්ට්-ලිටොව්ස්ක් ගිවිසුම (Treaty of Brest-Litovsk)", "වර්සායිල්ස් ගිවිසුම", "ජිනීවා සම්මුතිය", "පැරිස් ගිවිසුම", "1918 මාර්තු මස අත්සන් කළ මෙම ගිවිසුම මගින් රුසියාවට තම බටහිර භූමි ප්‍රදේශ රැසක් අත්හැරීමට සිදුවිය."),
    q(T, "රුසියානු විප්ලවයෙන් පසු රතු හමුදාව (Red Army) ගොඩනගා සිවිල් යුද්ධය ජයග්‍රහණය කරවූ අසහාය සෙන්පතියා කවුද?", "ලියොන් ට්‍රොට්ස්කි (Leon Trotsky)", "ව්ලැදිමීර් ලෙනින්", "ජෝසප් ස්ටාලින්", "නිකිටා කෲෂෙව්", "විදේශීය මැදිහත්වීම් සහ සුදු හමුදාවන් පරාජය කර සෝවියට් පාලනය තහවුරු කිරීමට ට්‍රොට්ස්කිගේ රතු හමුදාව සමත් විය."),
    q(T, "ලෙනින්ගේ මරණයෙන් පසු සෝවියට් සංගමයේ පාලනය භාරගෙන කෘෂිකාර්මික සාමූහිකකරණය සහ පස්වසර සැලසුම් ක්‍රියාත්මක කළ නායකයා කවුද?", "ජෝසප් ස්ටාලින් (Joseph Stalin)", "ලියොන් ට්‍රොට්ස්කි", "මිහායිල් ගොර්බචොෆ්", "බ්‍රෙෂ්නෙව්", "ස්ටාලින්ගේ වේගවත් කාර්මිකකරණය යටතේ සෝවියට් සංගමය ලෝකයේ ප්‍රබල කාර්මික හා මිලිටරි සුපිරි බලවතෙකු බවට පත්විය."),
    q(T, "පළමු ලෝක යුද්ධය ආරම්භ වීමට ආසන්නතම ක්ෂණික හේතුව වූයේ කුමන සිදුවීමද?", "ඔස්ට්‍රියාවේ ෆ්‍රාන්ස් ෆර්ඩිනන්ඩ් කුමරු සරායේවෝහිදී ඝාතනය වීම", "රුසියාව ජර්මනිය ආක්‍රමණය කිරීම", "බ්‍රිතාන්‍ය නාවික අවහිරය", "ඇමරිකාව යුද්ධයට ඒම", "1914 ජූනි 28 බොස්නියාවේ සරායේවෝහිදී ගව්රිලෝ ප්‍රින්සිප් නම් සර්බියානු ජාතිකවාදියා විසින් ඔස්ට්‍රියානු ඔටුන්න හිමි කුමරු ඝාතනය කරන ලදී."),
    q(T, "පළමු ලෝක යුද්ධයේදී 'ත්‍රිත්ව මිත්‍ර සන්ධානයට' (Triple Entente) අයත් වූ ප්‍රධාන රටවල් තුන කවරේද?", "බ්‍රිතාන්‍යය, ප්‍රංශය සහ රුසියාව", "ජර්මනිය, ඔස්ට්‍රියාව සහ ඉතාලිය", "ඇමරිකාව, ජපානය සහ චීනය", "තුර්කිය, බල්ගේරියාව සහ ඔස්ට්‍රියාව", "මෙම රටවල් තුන ජර්මනිය සහ ඔස්ට්‍රියා-හංගේරියාව ප්‍රමුඛ මධ්‍යම බලවතුන්ට එරෙහිව යුද වැදුණි."),
    q(T, "පළමු ලෝක යුද්ධය නිමාවට පත්කරමින් ක්‍රි.ව. 1919 දී මිත්‍ර ජාතීන් සහ ජර්මනිය අතර අත්සන් තැබූ ගිවිසුම කුමක්ද?", "වර්සායිල්ස් ගිවිසුම (Treaty of Versailles)", "පැරිස් ගිවිසුම", "වියානා සම්මුතිය", "ලොකාර්නෝ ගිවිසුම", "ජර්මනිය මත දැඩි යුද වන්දි සහ හමුදා සීමා පැනවූ මෙම ගිවිසුම දෙවන ලෝක යුද්ධයට බීජ වැපිරීමක් ලෙස සැලකේ."),
    q(T, "පළමු ලෝක යුද්ධයෙන් පසු ලෝක සාමය ආරක්ෂා කිරීම සඳහා පිහිටුවන ලද ජාත්‍යන්තර සංවිධානය කුමක්ද?", "ජාතීන්ගේ සංගමය (League of Nations)", "එක්සත් ජාතීන්ගේ සංවිධානය", "යුරෝපා සංගමය", "නැටෝ සංවිධානය", "ඇමරිකානු ජනාධිපති වුඩ්රෝ විල්සන්ගේ කරුණු 14 පදනම් කරගනිමින් ජිනීවා නුවර මූලස්ථානය කරගෙන ජාතීන්ගේ සංගමය පිහිටුවන ලදී."),
    q(T, "ජාතීන්ගේ සංගමයේ මූලික දුර්වලතාවක් වූයේ කුමන ප්‍රබල රාජ්‍යය එහි සාමාජිකත්වය ලබා නොගැනීමද?", "ඇමරිකා එක්සත් ජනපදය", "බ්‍රිතාන්‍යය", "ප්‍රංශය", "ඉතාලිය", "ඇමරිකානු සෙනෙට් සභාව විසින් වර්සායිල්ස් ගිවිසුම අනුමත නොකිරීම නිසා ඇමරිකාව ජාතීන්ගේ සංගමයට එක් නොවීය."),
    q(T, "යුරෝපීය පුනරුදය සාහිත්‍ය ක්ෂේත්‍රයේ ඇති කළ ප්‍රධාන පරිවර්තනයක් වූයේ කුමක්ද?", "ලතින් භාෂාව වෙනුවට ස්වදේශීය ජාතික භාෂාවලින් (Vernacular) පොත්පත් ලිවීම", "ග්‍රන්ථ රචනය මුළුමනින්ම නැවතීම", "පොත් අතින් පමණක් ලිවීම", "ආගමික පොත් පමණක් මුද්‍රණය කිරීම", "ඉතාලි, ඉංග්‍රීසි, ප්‍රංශ, ජර්මන් වැනි එදිනෙදා ජනතාව කතා කළ භාෂාවලින් සාහිත්‍ය නිර්මාණ බිහිවිය."),
    q(T, "පුනරුද සමයේ විද්‍යාත්මක ක්‍රමවේදය (Scientific Method) සහ අනුභූතික නිරීක්ෂණය පිළිබඳ අදහස් ඉදිරිපත් කළ චින්තකයා කවුද?", "ශ්‍රීමත් ෆ්‍රැන්සිස් බේකන් (Francis Bacon)", "මැකියාවෙලි", "පෙට්‍රාක්", "තෝමස් ඇක්වයිනාස්", "පෙර නිගමන වෙනුවට අත්හදා බැලීම්, නිරීක්ෂණ සහ දත්ත විශ්ලේෂණය මගින් සත්‍ය සොයාගත යුතු බව බේකන් අවධාරණය කළේය."),
    q(T, "කාර්මික විප්ලවයේ දියුණුවත් සමග ලොව පුරා ප්‍රාග්ධනය, වෙළඳපොළ සහ අමුද්‍රව්‍ය සොයා යුරෝපීයයන් දියත් කළ ක්‍රියාදාමය කුමක්ද?", "නූතන යටත්විජිතවාදය සහ අධිරාජ්‍යවාදය (Colonialism & Imperialism)", "වැඩවසම් ක්‍රමය", "සමාජවාදය", "හුදකලාවාදය", "කාර්මික රටවල අතිරික්ත නිෂ්පාදන අලෙවි කිරීමට සහ ලාභ අමුද්‍රව්‍ය ලබාගැනීමට ආසියාව සහ අප්‍රිකාව ආක්‍රමණය කර යටත් කරගන්නා ලදී."),
    q(T, "මානවවාදී චින්තනයේ පියා ලෙස සලකනු ලබන ඉතාලි ජාතික පුනරුද යුගයේ කවියා කවුද?", "ප්‍රැන්චෙස්කෝ පෙට්‍රාක් (Francesco Petrarch)", "බොකෑචියෝ", "ඩාන්ටේ", "මැකියාවෙලි", "පැරණි ග්‍රීක හා රෝම සම්භාව්‍ය සාහිත්‍යය යළි අධ්‍යයනය කරමින් මානවවාදයේ පදනම දැමූ පුරෝගාමියා පෙට්‍රාක් වේ."),
    q(T, "නූතන දේශපාලන විද්‍යාවේ පියා ලෙස සැලකෙන නිකොලෝ මැකියාවෙලි විසින් පාලකයන්ගේ උපක්‍රම විග්‍රහ කළ කෘතිය කුමක්ද?", "ද ප්‍රින්ස් හෙවත් කුමාරයා (The Prince)", "යුතෝපියාව", "දිව්‍ය ප්‍රහසනය", "සමාජ සම්මුතිය", "රාජ්‍ය බලය රැකගැනීම සඳහා සදාචාරයට වඩා ප්‍රායෝගික දේශපාලන උපක්‍රම වැදගත් බව මැකියාවෙලි මෙහිදී පෙන්වා දුන්නේය."),
    q(T, "සර් තෝමස් මෝර් විසින් පරමාදර්ශී සමානාත්මතාවයෙන් යුත් දූපත් රාජ්‍යයක් ගැන ලියූ කෘතිය කුමක්ද?", "යුතෝපියාව (Utopia)", "ද ප්‍රින්ස්", "දොන් කිහෝතේ", "කැන්ටබරි කතා", "පෞද්ගලික දේපළ නොමැති, සියලු දෙනාම එකමුතුව සතුටින් වෙසෙන සමාජයක් පිළිබඳ පරිකල්පනයක් මෝර් විසින් ඉදිරිපත් කරන ලදී."),
    q(T, "ප්‍රඥාවන්ත උපහාසයක් ඔස්සේ කතෝලික පල්ලියේ දූෂණ විවේචනය කරමින් ඩෙසිඩේරියස් එරස්මස් ලියූ කෘතිය කුමක්ද?", "මෝඩකමේ ප්‍රශංසාව (The Praise of Folly)", "යුතෝපියාව", "දිව්‍ය ප්‍රහසනය", "කුමාරයා", "උපහාසාත්මක සාහිත්‍ය නිර්මාණයක් වූ මෙම කෘතිය ආගමික ප්‍රතිසංස්කරණ ව්‍යාපාරයට පෙරමග සකස් කළේය."),
    q(T, "ක්‍රි.ව. 1517 දී කතෝලික පල්ලියේ පව් කමාවේ සහතික (Indulgences) විකිණීමට එරෙහිව 'තීසිස් 95' ඉදිරිපත් කළේ කවුද?", "මාටින් ලූතර් (Martin Luther)", "ජෝන් කැල්වින්", "ස්විංග්ලි", "ඉග්නේෂස් ලොයෝලා", "ජර්මනියේ විටන්බර්ග් පල්ලියේ දොරටුවේ තීසිස් 95 ඇණ ගැසීමෙන් යුරෝපීය ප්‍රොතෙස්තන්ත ප්‍රතිසංස්කරණ ව්‍යාපාරය ආරම්භ විය."),
    q(T, "මාටින් ලූතර් විසින් ආරම්භ කරන ලද ආගමික ප්‍රතිසංස්කරණ ව්‍යාපාරය හැඳින්වෙන්නේ කුමන නමින්ද?", "ප්‍රොතෙස්තන්ත ප්‍රතිසංස්කරණය (Protestant Reformation)", "ප්‍රති-ප්‍රතිසංස්කරණය", "පුනරුදය", "බුද්ධි ප්‍රබෝධය", "පාප්තුමාගේ අධිකාරිත්වය සහ පල්ලියේ පූජක ආධිපත්‍යය ප්‍රතික්ෂේප කරමින් ඇදහිල්ල මගින් ගැළවීම ලැබිය හැකි බව ලූතර් ඉගැන්වීය."),
    q(T, "ස්විට්සර්ලන්තයේ ජිනීවා නුවර කේන්ද්‍ර කරගනිමින් දැඩි ආගමික විනයක් සහිත ප්‍රතිසංස්කරණයක් මෙහෙයවූ නායකයා කවුද?", "ජෝන් කැල්වින් (John Calvin)", "මාටින් ලූතර්", "ස්විංග්ලි", "හෙන්රි රජු", "කැල්වින්වාදය (Calvinism) පසුව ප්‍රංශයේ හියුගනෝවරුන් හා බ්‍රිතාන්‍යයේ පියුරිටන්වරුන් අතර වේගයෙන් ව්‍යාප්ත විය."),
    q(T, "ප්‍රොතෙස්තන්ත ව්‍යාපාරයට ප්‍රතිචාර වශයෙන් කතෝලික සභාව තුළම ප්‍රතිසංස්කරණ ඇතිකළ 'ප්‍රති-ප්‍රතිසංස්කරණය' යටතේ රැස්වූ කවුන්සිලය කුමක්ද?", "ට්‍රෙන්ට් කවුන්සිලය (Council of Trent)", "වතිකානු කවුන්සිලය", "නයිසියා කවුන්සිලය", "කොන්ස්ටන්ස් කවුන්සිලය", "ක්‍රි.ව. 1545 සිට 1563 දක්වා පැවති ට්‍රෙන්ට් මන්ත්‍රණ සභාව කතෝලික ධර්මය පැහැදිලි කරමින් පල්ලියේ විනය ප්‍රතිසංවිධානය කළේය."),
    q(T, "ප්‍රති-ප්‍රතිසංස්කරණ සමයේදී 'යේසුස්ගේ සමාගම' හෙවත් ජේසුයිට් නිකාය (Jesuits) පිහිටුවූ ස්පාඤ්ඤ ජාතිකයා කවුද?", "ශාන්ත ඉග්නේෂස් ලොයෝලා (St. Ignatius of Loyola)", "මාටින් ලූතර්", "ජෝන් කැල්වින්", "ෆ්‍රැන්සිස් සේවියර්", "ලොයෝලා විසින් පිහිටුවූ ජේසුයිට්වරු අධ්‍යාපන ආයතන පිහිටුවමින් ලොව පුරා කතෝලික ධර්මය ප්‍රචාරය කිරීමට කැපවූහ."),
    q(T, "මිනිසා ස්වභාවයෙන්ම ජීවත්වීමේ, නිදහසේ සහ දේපළ හිමිකමේ 'ස්වාභාවික අයිතිවාසිකම්' (Natural Rights) සහිතව උපදින බව පැවසූ දාර්ශනිකයා කවුද?", "ජෝන් ලොක් (John Locke)", "තෝමස් හොබ්ස්", "ජෝන් ස්ටුවර්ට් මිල්", "කාල් මාක්ස්", "ආණ්ඩුවක ප්‍රධාන කාර්යය වන්නේ මෙම අයිතිවාසිකම් ආරක්ෂා කිරීම බව ජෝන් ලොක් තම දේශපාලන කෘති මගින් තර්ක කළේය."),
    q(T, "රාජ්‍යයක ව්‍යවස්ථාදායකය, විධායකය සහ අධිකරණය එකිනෙකින් වෙන්විය යුතු බවට 'බලතල බෙදීමේ න්‍යාය' (Separation of Powers) ඉදිරිපත් කළේ කවුද?", "මොන්ටෙස්කියු (Montesquieu)", "ජෝන් ලොක්", "ජෝන් කැල්වින්", "වෝල්ටෙයාර්", "මොන්ටෙස්කියුගේ 'නීතියේ ජීවය' (The Spirit of the Laws) කෘතිය ඇමරිකානු ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ මූලික සැලසුමට බෙහෙවින් බලපෑවේය."),
    q(T, "මිනිසා නිදහස්ව උපදින නමුත් සෑම තැනකදීම ඔහු යදම්වලින් බැඳී සිටින බව ප්‍රකාශ කරමින් 'සමාජ සම්මුතිය' (Social Contract) ලියූ චින්තකයා කවුද?", "ජෝන් ජැක් රූසෝ (Jean-Jacques Rousseau)", "වෝල්ටෙයාර්", "මොන්ටෙස්කියු", "ඩෙනිස් ඩිඩරෝ", "මහජන පරමාධිපත්‍යය (General Will) පදනම් කරගත් ප්‍රජාතන්ත්‍රවාදී සංකල්ප ප්‍රංශ විප්ලවයේ බුද්ධිමය ගාමක බලවේගය විය."),
    q(T, "භාෂණයේ නිදහස, මාධ්‍ය නිදහස සහ ආගමික ඉවසීම වෙනුවෙන් පෑන අවියක් කරගත් ප්‍රංශ බුද්ධි ප්‍රබෝධ යුගයේ සුප්‍රකට ලේඛකයා කවුද?", "වෝල්ටෙයාර් (Voltaire)", "රූසෝ", "ලොක්", "මැකියාවෙලි", "කැන්ඩයිඩ් (Candide) ඇතුළු කෘති ලියූ වෝල්ටෙයාර් ඒකාධිපති රාජ්‍ය පාලනය සහ ආගමික ආන්ධභක්තිය දැඩි ලෙස විවේචනය කළේය."),
    q(T, "බුද්ධි ප්‍රබෝධ සමයේ විද්‍යාත්මක හා මානව දැනුම එක්රැස් කරමින් ප්‍රථම මහා 'විශ්වකෝෂය' (Encyclopedie) සංස්කරණය කළ ප්‍රංශ චින්තකයා කවුද?", "ඩෙනිස් ඩිඩරෝ (Denis Diderot)", "රූසෝ", "වෝල්ටෙයාර්", "මොන්ටෙස්කියු", "ඩිඩරෝ සහ ඩි ඇලම්බර්ට් එක්ව සම්පාදනය කළ මෙම විශ්වකෝෂය විද්‍යාත්මක චින්තනය සමාජගත කිරීමේ මහා කර්තව්‍යයක් විය."),
    q(T, "නූතන ආර්ථික විද්‍යාවේ පියා ලෙස සැලකෙන, 'ජාතීන්ගේ ධනය' (The Wealth of Nations) කෘතිය ලියූ ස්කොට්ලන්ත ජාතිකයා කවුද?", "ඇඩම් ස්මිත් (Adam Smith)", "ඩේවිඩ් රිකාඩෝ", "කාල් මාක්ස්", "තෝමස් මැල්තස්", "රාජ්‍ය මැදිහත්වීමකින් තොර නිදහස් වෙළඳපොළ ආර්ථිකය (Laissez-faire) සහ ශ්‍රම විභජනයේ වැදගත්කම ඇඩම් ස්මිත් විග්‍රහ කළේය."),
    q(T, "ක්‍රි.ව. 1829 දී පැවති රේන්හිල් අත්හදා බැලීමේදී ජයග්‍රහණය කරමින් දුම්රිය යුගය සනිටුහන් කළ ජෝර්ජ් ස්ටීවන්සන්ගේ දුම්රිය එන්ජිම කුමක්ද?", "රොකට් (Rocket)", "පෆිං බිලී", "ලොකොමෝෂන්", "බ්ලූචර්", "පැයට සැතපුම් 29 ක වේගයෙන් ධාවනය වූ රොකට් දුම්රිය එන්ජිම ලිවර්පූල්-මැන්චෙස්ටර් දුම්රිය මාර්ගයේ සාර්ථකව ධාවනය කෙරිණි."),
    q(T, "ඇමරිකාවේ හඩ්සන් ගංගාවේ සාර්ථකව ධාවනය කළ ප්‍රථම වාෂ්ප නෞකාව වූ 'ක්ලෙයාර්මොන්ට්' (Clermont) නිර්මාණය කළේ කවුද?", "රොබට් ෆුල්ටන් (Robert Fulton)", "ජෝර්ජ් ස්ටීවන්සන්", "ජේම්ස් වොට්", "තෝමස් එඩිසන්", "වාෂ්ප බලයෙන් ක්‍රියාත්මක වූ බෝට්ටු මගින් ගංගා සහ සාගර තරණය කිරීමේ නව ප්‍රවාහන විප්ලවයක් ආරම්භ විය."),
    q(T, "ක්‍රි.ව. 1844 දී විදුලි විදුලි පණිවුඩ ක්‍රමය (Telegraph) සහ ඒ සඳහා සංකේත ක්‍රමයක් (Morse Code) නිපදවූයේ කවුද?", "සැමුවෙල් මෝර්ස් (Samuel Morse)", "ඇලෙක්සැන්ඩර් ග්‍රැහැම් බෙල්", "ගුග්ලියෙල්මෝ මාකෝනි", "තෝමස් එඩිසන්", "දුරස්ථ සන්නිවේදනය තත්පර ගණනකින් සිදුකිරීමට මෝර්ස්ගේ විදුලි පණිවුඩ පද්ධතිය මග පෑදීය."),
    q(T, "ක්‍රි.ව. 1876 දී ප්‍රථම වරට කටහඬ විදුලි සංඥා ඔස්සේ යැවිය හැකි 'දුරකථනය' (Telephone) නිපදවූ නව නිපැයුම්කරු කවුද?", "ඇලෙක්සැන්ඩර් ග්‍රැහැම් බෙල් (Alexander Graham Bell)", "තෝමස් එඩිසන්", "සැමුවෙල් මෝර්ස්", "නිකොලා ටෙස්ලා", "බෙල් විසින් දුරකථනය නිපදවීම ලෝක සන්නිවේදන ක්ෂේත්‍රයේ දැවැන්ත පෙරළියකට මග පෑදීය."),
    q(T, "විදුලි බුබුල, ශබ්දවාහිනී යන්ත්‍රය (Gramophone) සහ චලන චිත්‍ර කැමරාව ඇතුළු නව නිපැයුම් දහසකට අධික සංඛ්‍යාවක් කළ විද්‍යාඥයා කවුද?", "තෝමස් අල්වා එඩිසන් (Thomas Alva Edison)", "නිකොලා ටෙස්ලා", "මයිකල් ෆැරඩේ", "හෙන්රි ෆෝඩ්", "එඩිසන්ගේ ප්‍රායෝගික විදුලි ආලෝකකරණ පද්ධතිය ලෝකයේ කාර්මික හා ගෘහස්ථ ජීවිතය මුළුමනින්ම වෙනස් කළේය."),
    q(T, "කාර්මික විප්ලවයේ දියුණුවත් සමග මෝටර් රථ නිෂ්පාදනය සඳහා 'එකලස් කිරීමේ පේළි ක්‍රමය' (Assembly Line) හඳුන්වා දුන්නේ කවුද?", "හෙන්රි ෆෝඩ් (Henry Ford)", "තෝමස් එඩිසන්", "කාල් බෙන්ස්", "ගොට්ලීබ් ඩේම්ලර්", "ෆෝඩ් මොඩල් ටී (Model T) රථය මහා පරිමාණයෙන් නිපදවීම මගින් මෝටර් රථ සාමාන්‍ය ජනතාවට මිලදී ගත හැකි මට්ටමට පත් විය."),
    q(T, "කාර්මික විප්ලවයේ කටුක ප්‍රතිඵලයක් ලෙස බ්‍රිතාන්‍යයේ කම්කරුවන්ගේ ඡන්ද අයිතිය හා පාර්ලිමේන්තු ප්‍රතිසංස්කරණ ඉල්ලා ඇරඹි ව්‍යාපාරය කුමක්ද?", "චාටිස්ට් ව්‍යාපාරය (Chartist Movement)", "ලූඩයිට් ව්‍යාපාරය", "බොයිකොට් ව්‍යාපාරය", "සමාජවාදී ලීගය", "1838 දී 'මහජන ප්‍රඥප්තිය' (People's Charter) ඉදිරිපත් කරමින් සර්වජන ඡන්ද බලය සහ රහස් ඡන්ද ක්‍රමය චාටිස්ට්වරු ඉල්ලා සිටියහ."),
    q(T, "කාර්මික විප්ලවය නිසා ඇතිවූ පන්ති සටන සහ ධනවාදයේ බිඳවැටීම පිළිබඳව 'කොමියුනිස්ට් ප්‍රකාශනය' (The Communist Manifesto) ලියූ දාර්ශනිකයන් දෙදෙනා කවුද?", "කාල් මාක්ස් සහ ෆ්‍රෙඩ්රික් එංගල්ස් (Karl Marx & Friedrich Engels)", "ලෙනින් සහ ට්‍රොට්ස්කි", "ඇඩම් ස්මිත් සහ රිකාඩෝ", "රූසෝ සහ වෝල්ටෙයාර්", "1848 දී ප්‍රකාශයට පත් කළ මෙම කෘතිය ලෝක නිර්ධන පන්ති විප්ලවයන්ට දෘෂ්ටිවාදාත්මක මගපෙන්වීම ලබා දුන්නේය."),
    q(T, "ඇමරිකානු නිදහස් සටනේදී ජනතාව අතර විමුක්තිකාමී හැඟීම් ඇවිලවූ 'පොදු බුද්ධිය' (Common Sense) නම් පත්‍රිකාව ලියූ ලේඛකයා කවුද?", "තෝමස් පේන් (Thomas Paine)", "තෝමස් ජෙෆර්සන්", "බෙන්ජමින් ෆ්‍රැන්ක්ලින්", "ජෝර්ජ් වොෂිංටන්", "බ්‍රිතාන්‍ය කිරීටයෙන් මුළුමනින්ම වෙන්වී ස්වාධීන ජනරජයක් පිහිටුවීමේ අවශ්‍යතාව තෝමස් පේන් සරල බසින් ජනතාවට පහදා දුන්නේය."),
    q(T, "ඇමරිකානු විප්ලවයට ආධාර කිරීම සඳහා ස්වේච්ඡාවෙන් පැමිණි ප්‍රංශ ජාතික වංශවත් සෙන්පතියා කවුද?", "ලාෆයෙට් සාමිවරයා (Marquis de Lafayette)", "රොබෙස්පියර්", "නැපෝලියන්", "මිහායිල් කුටුසොෆ්", "ජෝර්ජ් වොෂිංටන්ගේ සමීප මිතුරෙකු වූ ලාෆයෙට් ඇමරිකානු හමුදාව සංවිධානය කිරීමට සහ ප්‍රංශ සහාය ලබාගැනීමට කැප විය."),
    q(T, "ක්‍රි.ව. 1777 දී ඇමරිකානු හමුදා බ්‍රිතාන්‍ය හමුදාව පරාජය කර යුද්ධයේ හැරවුම් ලක්ෂ්‍යය සනිටුහන් කළ සටන කුමක්ද?", "සරටෝගා සටන (Battle of Saratoga)", "ලෙක්සිංටන් සටන", "යෝර්ක්ටවුන් සටන", "ට්‍රෙන්ටන් සටන", "සරටෝගා ජයග්‍රහණයෙන් පසු ප්‍රංශය සහ ස්පාඤ්ඤය ඇමරිකානුවන්ට විවෘතව යුද ආධාර සැපයීමට ඉදිරිපත් විය."),
    q(T, "ක්‍රි.ව. 1783 දී ඇමරිකා එක්සත් ජනපදයේ ස්වාධීනත්වය බ්‍රිතාන්‍යය විසින් නිල වශයෙන් පිළිගන්නා ලද ගිවිසුම කුමක්ද?", "පැරිස් ගිවිසුම 1783 (Treaty of Paris)", "වර්සායිල්ස් ගිවිසුම", "ලන්ඩන් ගිවිසුම", "වොෂිංටන් ගිවිසුම", "මෙම ගිවිසුම මගින් ඇමරිකා එක්සත් ජනපදය නිදහස්, ස්වෛරී රාජ්‍යයක් බව බ්‍රිතාන්‍ය රජු නිල වශයෙන් පිළිගත්තේය."),
    q(T, "ඇමරිකානු ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ පියා (Father of the Constitution) ලෙස සලකනු ලබන්නේ කවුද?", "ජේම්ස් මැඩිසන් (James Madison)", "තෝමස් ජෙෆර්සන්", "ජෝර්ජ් වොෂිංටන්", "ඇලෙක්සැන්ඩර් හැමිල්ටන්", "1787 ෆිලඩෙල්ෆියා සම්මේලනයේදී නව ආණ්ඩුක්‍රම ව්‍යවස්ථාව කෙටුම්පත් කිරීමට සහ අයිතිවාසිකම් පනත (Bill of Rights) එක්කිරීමට මැඩිසන් මූලික විය."),
    q(T, "ප්‍රංශ විප්ලවයේදී ව්‍යවස්ථාදායක සභාව රැස්වූ විට වඩාත් රැඩිකල් රැස්වීම්කරුවන් වාඩිවූයේ කුමන පැත්තේ නිසා 'වාමාංශික' (Left-wing) යෙදුම බිහිවූයේද?", "සභාපතිවරයාගේ වම් පැත්තේ වාඩිවීම නිසා", "දකුණු පැත්තේ වාඩිවීම නිසා", "මැද වාඩිවීම නිසා", "පිටත වාඩිවීම නිසා", "ප්‍රංශ පාර්ලිමේන්තුවේ රැඩිකල් වෙනස්කම් ඉල්ලූ ජැකොබින්වරු වම්පස අසුන්ගත් අතර එතැන් සිට විප්ලවවාදී හෝ සමාජවාදී මතධාරීන් 'වාමාංශිකයින්' ලෙස හැඳින්විණි."),
    q(T, "ප්‍රංශ විප්ලව සමයේ මධ්‍යස්ථ මතධාරී රිපබ්ලිකානුවන් හැඳින්වූයේ කුමන කණ්ඩායම් නාමයෙන්ද?", "ජිරොන්ඩින්වරු (Girondins)", "ජැකොබින්වරු", "රාජපාක්ෂිකයෝ", "බොල්ෂෙවික්වරු", "ප්‍රංශයේ ජිරොන්ඩේ ප්‍රදේශයෙන් පැමිණි නියෝජිතයන් වූ මොවුන් ආණ්ඩුක්‍රම ව්‍යවස්ථානුකූල පාලනයක් හා වඩා මධ්‍යස්ථ ප්‍රතිසංස්කරණ ප්‍රිය කළහ."),
    q(T, "ප්‍රංශ විප්ලවයේ අන්තවාදී ජැකොබින් කණ්ඩායමේ පුවත්පත් කලාවේදියෙකු වූ ජීන්-පෝල් මාරා ඝාතනය කළ තරුණිය කවුද?", "චාලට් කෝර්ඩේ (Charlotte Corday)", "මාරි ඇන්ටොයිනෙට්", "ජොආන් ඔෆ් ආක්", "මැඩම් රෝලන්ඩ්", "ජිරොන්ඩින් හිතවාදිනියක වූ චාලට් කෝර්ඩේ විසින් මාරා තම නාන තටාකයේ සිටියදී පිහියෙන් ඇන ඝාතනය කරන ලදී."),
    q(T, "ප්‍රංශ විප්ලවයේ භීෂණ පාලන සමයේදී ප්‍රංශය පාලනය කළ බලගතු කමිටුව කුමක්ද?", "මහජන ආරක්ෂක කමිටුව (Committee of Public Safety)", "ජාතික විධායක සභාව", "යුද කමිටුව", "විප්ලවවාදී උසාවිය", "රොබෙස්පියර් ප්‍රමුඛ සාමාජිකයන් 12 දෙනෙකුගෙන් යුත් මෙම කමිටුව රටේ පරම බලය අතට ගෙන දහස් ගණනක් මරා දැමීය."),
    q(T, "නැපෝලියන් බොනපාට් 1799 දී ප්‍රංශයේ බලය අල්ලා ගත් කුමන්ත්‍රණය හැඳින්වෙන්නේ කුමන නමින්ද?", "බෘමේර් 18 කුමන්ත්‍රණය (Coup of 18 Brumaire)", "බැස්ටීල දිනය", "තර්මිඩෝරියානු ප්‍රතික්‍රියාව", "ජූලි විප්ලවය", "දුර්වල ඩිරෙක්ටරි පාලනය පෙරළා දමා නැපෝලියන් ප්‍රංශයේ 'පළමු කොන්සල්වරයා' බවට පත්විය."),
    q(T, "නැපෝලියන් බොනපාට්ගේ බ්‍රිතාන්‍යය ආර්ථික වශයෙන් වටලෑමේ අරමුණින් ක්‍රියාත්මක කළ වෙළඳ අවහිර ප්‍රතිපත්තිය කුමක්ද?", "මහාද්වීපික ක්‍රමය (Continental System)", "නාවික පනත", "නිදහස් වෙළඳාම", "අත්ලාන්තික් සම්මුතිය", "බ්‍රිතාන්‍ය භාණ්ඩ යුරෝපයට ඇතුළුවීම තහනම් කළ මෙම ක්‍රමය අසාර්ථක වූ අතර නැපෝලියන්ට එරෙහිව යුරෝපීය ජාතීන් නැගී සිටීමට හේතු විය."),
    q(T, "ක්‍රි.ව. 1812 දී නැපෝලියන් රුසියාව ආක්‍රමණය කළ අවස්ථාවේ රුසියානු හමුදා අනුගමනය කළ යුද උපක්‍රමය කුමක්ද?", "දැවී ගිය භූමි ප්‍රතිපත්තිය (Scorched Earth Policy)", "අගල් යුද්ධය", "ගරිල්ලා යුද්ධය", "මුහුදු වටලෑම", "ආක්‍රමණිකයන්ට කිසිදු ආහාරයක් හෝ නවාතැනක් නොතබා පසුබසිමින් මොස්කව් නුවර පවා ගිනිබත් කර රුසියානු ශීත ඍතුවේදී නැපෝලියන්ගේ හමුදාව විනාශ කළහ."),
    q(T, "රුසියානු සාර් පාලනයට එරෙහිව 1917 මාර්තු මස ශාන්ත පීටර්ස්බර්ග් නුවර ඇතිවූ විරෝධතා ආරම්භ කළේ කවුරුන්ද?", "පාන් ඉල්ලා පෙළපාලි ගිය කාන්තා කම්කරුවන්", "විශ්වවිද්‍යාල මහාචාර්යවරුන්", "විදේශීය හමුදා", "ධනවත් ව්‍යාපාරිකයන්", "කාන්තා දිනයේදී ආරම්භ වූ පාන් කෝලාහල සාමාන්‍ය වැඩවර්ජනයක් දක්වා වර්ධනය වී සාර් රජුගේ සිහසුන අහිමි කිරීමට සමත් විය."),
    q(T, "ක්‍රි.ව. 1917 අප්‍රේල් මස පිටුවහල්ව සිට රුසියාවට පැමිණි ලෙනින් ඉදිරිපත් කළ සුප්‍රකට ප්‍රතිපත්ති ප්‍රකාශය කුමක්ද?", "අප්‍රේල් තීසිස් (April Theses)", "ඔක්තෝබර් ප්‍රකාශනය", "කොමියුනිස්ට් ප්‍රඥප්තිය", "සාම ආඥාව", "තාවකාලික ආණ්ඩුවට සහාය නොදක්වා සියලු බලය සෝවියට් සභාවලට ලබාගත යුතු බව ලෙනින් මෙහිදී ප්‍රකාශ කළේය."),
    q(T, "1917 ඔක්තෝබර් විප්ලවයේදී බොල්ෂෙවික් හමුදා ප්‍රහාර එල්ල කර අල්ලා ගත් තාවකාලික ආණ්ඩුවේ මූලස්ථානය කුමක්ද?", "ශීත ඍතු මාලිගය (Winter Palace)", "ක්‍රෙම්ලිනය", "බැස්ටීලය", "වර්සායිල්ස්", "අරෝරා නැවේ කාලතුවක්කු වෙඩි හඬත් සමග රතු ආරක්ෂකයන් ශීත ඍතු මාලිගයට කඩා වැදී තාවකාලික ආණ්ඩුවේ ඇමතිවරුන් අත්අඩංගුවට ගත්හ."),
    q(T, "රුසියානු සිවිල් යුද්ධයේදී (1918-1921) බොල්ෂෙවික් රතු හමුදාවට එරෙහිව සටන් කළ සාර්වාදී හා ධනපති හමුදා හැඳින්වූයේ කුමන නමින්ද?", "සුදු හමුදාව (White Army)", "කළු හමුදාව", "හරිත හමුදාව", "මිත්‍ර හමුදාව", "බ්‍රිතාන්‍යය, ප්‍රංශය සහ ඇමරිකාව ඇතුළු විදේශ රටවල ආධාර ලැබූ සුදු හමුදාව ට්‍රොට්ස්කිගේ රතු හමුදාව හමුවේ පරාජය විය."),
    q(T, "රුසියානු ආර්ථිකය යථා තත්ත්වයට පත්කිරීම සඳහා ලෙනින් විසින් 1921 දී හඳුන්වා දුන් ආර්ථික ප්‍රතිපත්තිය කුමක්ද?", "නව ආර්ථික ප්‍රතිපත්තිය හෙවත් NEP (New Economic Policy)", "යුද කොමියුනිස්ට්වාදය", "සාමූහික ගොවිපළ ක්‍රමය", "පස්වසර සැලැස්ම", "සමාජවාදී රාමුව තුළ සුළු පරිමාණ පෞද්ගලික වෙළඳාමට සහ ගොවීන්ට අතිරික්ත අස්වැන්න විකිණීමට ඉඩ දීමෙන් ආර්ථිකය යථා තත්ත්වයට පත් විය."),
    q(T, "පුනරුද සමයේ ඉතාලියේ වෙළඳ නගර රාජ්‍යයන් (City-states) ලෙස ප්‍රබලව නැගී සිටි නගර මොනවාද?", "ෆ්ලෝරන්ස්, වැනිස්, ජිනෝවා සහ මිලාන්", "ලන්ඩන්, පැරිස්, මැඩ්‍රිඩ්", "බර්ලින්, මියුනිච්, වියානා", "මොස්කව්, කීව්, වෝර්සෝ", "මධ්‍යධරණී මුහුද හරහා පෙරදිග සමග කළ වෙළඳාම නිසා මෙම ඉතාලි නගර අතිමහත් ධනයක් උපයා පුනරුදයට අනුග්‍රහය දැක්වීය."),
    q(T, "මුද්‍රණ ශිල්පය සොයාගැනීම නිසා යුරෝපයේ ඇතිවූ ප්‍රධානතම සමාජීය පෙරළිය කුමක්ද?", "පොත්පත් මිල අඩුවී සාමාන්‍ය ජනයා අතර දැනුම හා සාක්ෂරතාව සීඝ්‍රයෙන් ව්‍යාප්ත වීම", "පොත්පත් කියවීම නතර වීම", "දැනුම රහසක් බවට පත්වීම", "පාසල් වැසී යාම", "අතින් ලියන ලද මිල අධික අත්පිටපත් වෙනුවට මුද්‍රිත පොත් දහස් ගණනින් බිහිවීම ලෝක බුද්ධිමය පුනරුදයට මහා තල්ලුවක් විය."),
    q(T, "ඇමරිකානු සිවිල් යුද්ධය (1861-1865) අවසානයේ වහල්භාවය මුළුමනින්ම අහෝසි කළ ඇමරිකානු ජනාධිපතිවරයා කවුද?", "ඒබ්‍රහම් ලින්කන් (Abraham Lincoln)", "ජෝර්ජ් වොෂිංටන්", "තෝමස් ජෙෆර්සන්", "ඇන්ඩෲ ජැක්සන්", "ගෙටිස්බර්ග් දේශනය පැවැත්වූ ලින්කන් එක්සත් ජනපදයේ වහල්භාවය මුලිනුපුටා දමමින් ජාතිය එක්සත් කළේය."),
    q(T, "කාර්මික විප්ලවයේදී බිහිවූ 'ලූඩයිට්වරු' (Luddites) නම් කණ්ඩායමේ සුවිශේෂී ක්‍රියාකාරකම වූයේ කුමක්ද?", "තම රැකියා අහිමි කරන බව පවසමින් කර්මාන්තශාලාවල යන්ත්‍ර සූත්‍ර කඩා බිඳ දැමීම", "නව යන්ත්‍ර නිපදවීම", "මුදල් ඉතිරි කිරීම", "පාර්ලිමේන්තුවට තේරී පත්වීම", "නෙඩ් ලුඩ්ගේ නායකත්වයෙන් රෙදි වියන්නන් යන්ත්‍රෝපකරණ විනාශ කිරීම මගින් කාර්මිකකරණයට දැඩි විරෝධය පෑහ."),
    q(T, "දෙවන ලෝක යුද්ධයට මග පෑදූ 'ෆැසිස්ට්වාදය' (Fascism) ඉතාලියේ ස්ථාපිත කළ ඒකාධිපති නායකයා කවුද?", "බෙනිටෝ මුසෝලිනි (Benito Mussolini)", "ඇඩොල්ෆ් හිට්ලර්", "ෆ්‍රැන්සිස්කෝ ෆ්‍රැන්කෝ", "ස්ටාලින්", "පළමු ලෝක යුද්ධයෙන් පසු ඉතාලියේ ඇතිවූ අස්ථාවරත්වය ප්‍රයෝජනයට ගනිමින් කළු කමිසධාරීන් මෙහෙයවා මුසෝලිනි බලය ඇල්ලීය."),
    q(T, "ජර්මනියේ 'නාසිවාදය' (Nazism) ඔස්සේ බලයට පත්ව දෙවන ලෝක යුද්ධයට සහ යුදෙව් සංහාරයට වගකිව යුතු වූ පාලකයා කවුද?", "ඇඩොල්ෆ් හිට්ලර් (Adolf Hitler)", "බෙනිටෝ මුසෝලිනි", "කයිසර් විල්හෙල්ම්", "බිස්මාර්ක්", "1933 දී ජර්මනියේ චාන්සලර් බවට පත්වූ හිට්ලර් ඒකාධිපති තුන්වන රයිෂ් පාලනය ගොඩනැගුවේය."),
    q(T, "ජපානය 1941 දෙසැම්බර් 7 වන දින ඇමරිකානු නාවික හමුදා කඳවුරකට එල්ල කළ ප්‍රහාරය හැඳින්වෙන්නේ කුමන නමින්ද?", "පර්ල් වරාය ප්‍රහාරය (Attack on Pearl Harbor)", "මිඩ්වේ සටන", "හිරෝෂිමා ප්‍රහාරය", "ඔකිනාවා සටන", "මෙම විනාශකාරී ප්‍රහාරය හේතුවෙන් නොබැඳිව සිටි ඇමරිකා එක්සත් ජනපදය නිල වශයෙන් දෙවන ලෝක යුද්ධයට අවතීර්ණ විය."),
    q(T, "දෙවන ලෝක යුද්ධය අවසන් කරමින් 1945 අගෝස්තු මස ඇමරිකාව විසින් පරමාණු බෝම්බ හෙළන ලද ජපානයේ නගර දෙක මොනවාද?", "හිරෝෂිමා සහ නාගසාකි (Hiroshima & Nagasaki)", "ටෝකියෝ සහ කියෝතෝ", "ඔසාකා සහ යොකොහාමා", "ෆුකුෂිමා සහ සපෝරෝ", "ලිට්ල් බෝයි සහ ෆැට් මෑන් නම් පරමාණු බෝම්බ ප්‍රහාර හමුවේ ජපානය කොන්දේසි විරහිතව යටත් වී දෙවන ලෝක යුද්ධය නිමාවිය."),
    q(T, "දෙවන ලෝක යුද්ධයෙන් පසු 1945 ඔක්තෝබර් 24 වන දින ලෝක සාමය හා ආරක්ෂාව තහවුරු කිරීමට පිහිටුවන ලද ආයතනය කුමක්ද?", "එක්සත් ජාතීන්ගේ සංවිධානය (United Nations)", "ජාතීන්ගේ සංගමය", "නේටෝ සංවිධානය", "වෝර්සෝ සංවිධානය", "සාමාජික රටවල් 51 ක සහභාගීත්වයෙන් සැන් ෆ්‍රැන්සිස්කෝහිදී එක්සත් ජාතීන්ගේ ප්‍රඥප්තිය අත්සන් කරන ලදී."),
    q(T, "එක්සත් ජාතීන්ගේ සංවිධානයේ මූලස්ථානය පිහිටා ඇත්තේ කුමන නගරයේද?", "ඇමරිකාවේ නිව්යෝක් නුවර (New York)", "ජිනීවා නුවර", "ලන්ඩන් නුවර", "පැරිස් නුවර", "ලෝක ජාතීන්ගේ මහා සභාව සහ ආරක්ෂක මණ්ඩලය නිව්යෝක්හි එක්සත් ජාතීන්ගේ මූලස්ථානයේදී රැස්වේ."),
    q(T, "එක්සත් ජාතීන්ගේ සංවිධානය විසින් 1948 දෙසැම්බර් 10 දින සම්මත කරන ලද ඓතිහාසික ලේඛනය කුමක්ද?", "මානව හිමිකම් පිළිබඳ විශ්ව ප්‍රකාශනය (UDHR)", "ජාත්‍යන්තර කම්කරු ප්‍රඥප්තිය", "ළමා අයිතිවාසිකම් ප්‍රඥප්තිය", "පාරිසරික ප්‍රඥප්තිය", "සෑම මිනිසෙකුටම හිමි මූලික නිදහස සහ අයිතිවාසිකම් ජාත්‍යන්තරව පිළිගත් සම්මුතියක් ලෙස මෙය ප්‍රකාශයට පත් කෙරිණි."),
    q(T, "පුනරුද සමයේ සංගීත ක්ෂේත්‍රයේ බිහිවූ විශිෂ්ටතම නිර්මාණකරුවෙකු ලෙස සැලකෙන්නේ කවුද?", "ජොවානි පියර්ලුයිජි ද පලෙස්ත්‍රිනා (Palestrina)", "මයිකල් ආන්ජලෝ", "මැකියාවෙලි", "බෘනලෙස්කි", "බහුවිධ ස්වර සංයෝජනය (Polyphony) සහිත කතෝලික පල්ලියේ පූජනීය සංගීතය නව තලයකට ඔසවා තැබූ සංගීතඥයෙකි."),
    q(T, "භූගෝලීය ගවේෂණ නිසා නව ලෝකයෙන් (ඇමරිකාවෙන්) පැරණි ලෝකයට (යුරෝපයට හා ආසියාවට) හඳුන්වා දුන් බෝග මොනවාද?", "අර්තාපල්, බඩඉරිඟු, තක්කාලි, මිරිස් සහ දුම්කොළ", "තේ, කෝපි, කුරුඳු, එනසාල්", "තිරිඟු, බාර්ලි, ඕට්ස්, සහල්", "කපු, රබර්, උක්, පොල්", "කොලොම්බියානු හුවමාරුව (Columbian Exchange) මගින් ලෝක කෘෂිකර්මාන්තය හා ආහාර පුරුදු සම්පූර්ණයෙන්ම වෙනස් විය."),
    q(T, "භූගෝලීය ගවේෂණවලින් පසු අත්ලාන්තික් සාගරය හරහා යුරෝපය, අප්‍රිකාව සහ ඇමරිකාව අතර සිදුවූ වෙළඳාම හැඳින්වූයේ කුමක් ලෙසද?", "ත්‍රිකෝණාකාර වෙළඳාම (Triangular Trade)", "සේද මාවත", "කුළුබඩු වෙළඳාම", "ඉන්දියන් සාගර වෙළඳාම", "යුරෝපයෙන් අප්‍රිකාවට භාණ්ඩද, අප්‍රිකාවෙන් ඇමරිකාවට වහලුන්ද, ඇමරිකාවෙන් යුරෝපයට සීනි හා දුම්කොළද ප්‍රවාහනය කළ අමානුෂික වෙළඳ ජාලයකි."),
    q(T, "කාර්මික විප්ලවය හේතුවෙන් ධනවාදී ආර්ථික ක්‍රමය තුළ බිහිවූ ප්‍රධාන සමාජ පන්ති දෙක කවරේද?", "ධනපති පන්තිය (Bourgeoisie) සහ කම්කරු පන්තිය (Proletariat)", "රජවරුන් සහ දාසයන්", "පූජකයන් සහ වංශවතුන්", "ගොවීන් සහ නයිට්වරුන්", "නිෂ්පාදන මාධ්‍ය හිමි ධනපතියන් සහ තම ශ්‍රමය විකුණා ජීවත්වන කම්කරුවන් අතර ඇතිවූ ආර්ථික පරතරය නූතන සමාජ ගැටුම්වලට මූලික විය."),
    q(T, "ඇමරිකා එක්සත් ජනපදයේ ආණ්ඩුක්‍රම ව්‍යවස්ථාව ලොව ප්‍රථම ලිඛිත ව්‍යවස්ථාව ලෙස සම්මත වූයේ කුමන වර්ෂයේදීද?", "ක්‍රි.ව. 1787 දී", "ක්‍රි.ව. 1776 දී", "ක්‍රි.ව. 1789 දී", "ක්‍රි.ව. 1791 දී", "ෆිලඩෙල්ෆියා සම්මේලනයේදී සකස් කර සම්මත කරගත් මෙම ව්‍යවස්ථාව අද දක්වාම ඇමරිකාවේ උත්තරීතර නීතිය ලෙස ක්‍රියාත්මක වේ."),
    q(T, "ප්‍රංශ විප්ලවයේ අවසානය සහ යුරෝපයේ ජාතිකවාදී හැඟීම් වර්ධනය වීමට බෙහෙවින් බලපෑ ඓතිහාසික ක්‍රියාවලිය කුමක්ද?", "නැපෝලියානු යුද්ධ (Napoleonic Wars)", "කුරුස යුද්ධ", "ශතවර්ෂ යුද්ධය", "තිස්වසර යුද්ධය", "නැපෝලියන් යුරෝපය පුරා කළ යුද ව්‍යාපාර හරහා ප්‍රංශ විප්ලවයේ නිදහස සහ ජාතිකවාදී අදහස් යුරෝපය පුරා ව්‍යාප්ත විය."),
    q(T, "1917 රුසියානු ඔක්තෝබර් විප්ලවයෙන් පසු කම්කරුවන්ගේ හා සෙබළුන්ගේ නියෝජිතයන්ගෙන් සමන්විත වූ ප්‍රාදේශීය සභා හැඳින්වූයේ කුමන නමින්ද?", "සෝවියට් සභා (Soviets)", "ඩූමාව", "පාර්ලිමේන්තුව", "කොමියුනය", "කම්හල් හා හමුදා කඳවුරු පදනම් කරගෙන පිහිටුවූ සෝවියට් සභා පසුව සෝවියට් රාජ්‍යයේ නිල පාලන ව්‍යුහය බවට පත්විය."),
    q(T, "මානව ඉතිහාසයේ විප්ලවයන් මගින් තහවුරු කරන ලද උසස්ම ප්‍රජාතන්ත්‍රවාදී අගය කුමක්ද?", "රාජ්‍ය පාලන බලයේ සැබෑ උල්පත මහජනතාව වන බව සහ මානව අයිතිවාසිකම් රැකීම", "රජවරුන්ගේ පරම අයිතිය", "හමුදා බලයෙන් රට පාලනය කිරීම", "ධනවතුන්ට පමණක් පාලන අයිතිය දීම", "ජනතාවගේ කැමැත්තෙන් තොරව පාලනයක් කළ නොහැකි බවත් නීතිය ඉදිරියේ සැමදෙනා සමාන බවත් මෙම විප්ලව ලොවට පසක් කළේය.")
  )
}
